-- Validated matched 100-post cohort. Seed only before recruitment.
begin;
do $$ begin
 if (select recruitment_open from public.matched100_settings where id)
    or exists(select 1 from public.matched100_participants where mode='formal')
 then raise exception 'Seed only before formal recruitment'; end if;
end $$;
create temporary table matched100_import(stimulus_id text,submission_id text,prompt_text text,prompt_sha256 text,body_sha256 text,word_limit integer) on commit drop;
alter table matched100_import enable row level security;
insert into matched100_import select * from jsonb_to_recordset($materials$[{"stimulus_id": "P001", "submission_id": "kwpddr", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nDisclaimer: Throwaway account, repost due to exceeding character count\n\nI (28F) live with two roommates, A (29F) and B (33F). We have lived together for 3 years in a two-story home and split the rent evenly. We share the living/dining/kitchen, but each have our own bedroom and bathroom. Because my room is about half the size of the other bedrooms, I also get the small bonus room, which is open to the shared spaces below.\n\nBecause of the pandemic, we all work from home. I use the bonus room as my work space, whereas roommates A and B originally worked from their rooms. At one point, roommate A moved her desk into the living room because she felt trapped in her room all day. Roommate B and I were a little annoyed because neither of us were consulted, but we tried to be understanding about it.\n\nOver the past few months, roommate A has gotten comfortable in the living room and now treats it as her home office. She works in a sales position and is on the phone for at least 2-3 hours a day. She also attends a lot of virtual meetings and lets the sound play over her speakers.\n\nIt's loud all the time. I purchased a pair of noise-cancelling headphones and have to take work calls from my room. Roommate B is largely unaffected because she works in her room, but told me that she can no longer watch TV or hang out in the living room because roommate A often works during lunch or late into the evenings.\n\nRecently, roommate A and I got into an argument over her using the living room as her office. It  started with her complaint about my keyboard noise. I acknowledged that my mechanical keyboard is obnoxiously loud and bought a set of O-rings to dampen the noise, but the complaints continued. I wear noise-cancelling headphones all day to get through her noise and suggested she do the same.\n\nShe refused due to headphones being uncomfy, so I bought her a box of the highest decibel-blocking earplugs I could find. This was not an acceptable solution as her coworkers could still hear click-clack sounds on calls and that instead, she wanted me to move my desk into my room. This is not an option for me because my room barely fits my bed and wardrobe, so I told her I would get a quieter keyboard if we could split the cost. She refused and said I could pay for it myself or find a way to fit my work space into my room.\n\nI have the right to the office space as part of our roommate agreement and if anyone is moving their desk into their room, it should be her. She wasn't budging on her position, so I made a low blow and told her she basically broadcasts all her work calls and I have absorbed enough information about her job to report her to her for breaking whatever company NDAs she's under. And ultimately, she moved her desk back to her room.\n\nShe says I'm the AH because I have a dedicated home office and am not being compassionate about her situation, but I really have tried to be despite her being an inconsiderate roommate. AITA for not letting her use the living room?", "prompt_sha256": "078f06922c7b69d1fbeed663105fa52195bf7dc7cb8c433a42750e46d5a61f04", "body_sha256": "7a0e1b3b99a233f474478afbdf5d40a5ead7abf7bc85336f208909a0840e0322", "word_limit": 61}, {"stimulus_id": "P002", "submission_id": "18i7ozr", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nI got married a year ago and my photographer had an offer to create a professional wedding album with just the bride and groom. Previously for the wedding video I wasn’t asked about what songs I want to add to the video or anything. They decided to do everything themselves . I said nothing as I thought it’s okay they’re not gonna choose anything bad. \n I was so excited for the album as the pictures turned out really good and would be even better in an album. My in laws didn’t let me know the photographer asked for photos for the album. I was coincidentally at their home when they were choosing the pictures and they didn’t find it important to include me to see them. I kindly requested to see them . I did and it did not include the family members I wanted and mainly included all the inlaws extended family. This made me furious but held it in. I asked calmly if more could be added and was told no as there is a limited amount of space in the album. \nThis made me even more angry because some pictures were so unnecessary . I stormed out of the living room because I wanted to calm myself down. \nThen MIL comes in and tells me I shouldn’t have stormed out like that over small things and that I don’t act like a proper DIL and started teaching me manners . She also said the album isn’t for us anyways it’s for herself and that she’s only adding people that are important to her. DH was shocked too because the whole time we both thought it’s for us .", "prompt_sha256": "57f992577373d092a4b845012004f33393bece1247295bbf902c8add471c1a8e", "body_sha256": "1605d7ecfd7efd0ec8f1470f1aefe40714c22229704becb6ac4e33f6058c4b39", "word_limit": 61}, {"stimulus_id": "P003", "submission_id": "15xr0t0", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\n\nMy 25F and my friend Sarah 29F about 2 years ago she had a strawberry size lesion on her thigh  which is about 3 CM and it turned to be early stage of skin cancer all the did back then was excised it under local anesthesia too and they told her it was over and she doesn’t have it anymore.\n\n\n\nToday i was with her and mutual friend, our mutual friend has a recurrent abdominal pain and he will do an exploratory laparotomy to know the cause and he kept talking about how scared he is and then sarah came and threw the cancer card.\n\n\nShe started talking about “ how she survived cancer and how it destroyed her life and he will be fine and she understand how he feels etc”\n\n\nI snapped at her and told her it’s misleading of her to call herself as a cancer survivor because what she had backthen was almost nothing and just a lesion on the skin.\n\nAnd when people hear the world “ cancer survivor “ they would think about someone who took chemotherapy and almost died because of it but in her case it was nothing just a removal with a small incision in the clinic.\n\nI thought others would have my back but they said i’m an AH and that left me wondering did i say something wrong?", "prompt_sha256": "aa9f0a4e29d184b6926eae7c447ca6124056f33aa4dde4846509ee2e9890ffc7", "body_sha256": "fdfe06e2d0c0725801908d0cad0f9f8916c9ce0605323b17e17bf2325790e656", "word_limit": 61}, {"stimulus_id": "P004", "submission_id": "lxr5ho", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nDisclaimer: Not my but a friend's question. Posted with his permission and on his request. \n\nThe title sounds bad, but hear me out. I (32M) have a daughter (7F) with my wife (36F). My wife also has a son Jake (13) from her previous marriage to, say Bill (38 M). \n\nI have a great relationship with my stepson. He's a great kid who is really into sports and outdoorsy stuff like I am. So we get along fabulously. I am also on cordial terms with Bill as he and my wife have shared custody of Jake. Bill used to be an outdoorsy person as well, until an unfortunate accident 5 years ago which left him wheelchair bound. \n\nUsually on Father's day, I would take my daughter out somewhere (she has recently discovered the joys of hiking) and my stepson would go out on fun trips with Bill. But since the last 5 years Bill hasn't been able to take his son out the way he used to. I have noticed Jake being unhappy about it. Especially since I try to make the day special for my daughter. And while I make a point to not mention any of it to Jake, my daughter is a chatterbox who pours out everything in front of her mother and brother. \n\nBill has noticed this too. And once when I was dropping Jake off at his place, he invited me in for a beer and we spoke. It was disheartening to say the least. Bill broke down and confessed he was scared of being completely replaced out of Jake's life. (Jake hadn't done anything mean. He was just less excited about being with Bill than he used to earlier). \n\nI assured Bill that would never happen. I mean there is no denying that Jake still loves his father with all his heart. He's just a bit bummed out at not being able to do the things he used to do. \n\nAnyway, last year on father's day, I had managed to arrange a small but nice outing (Covid Safe) with my daughter. \n\nJake was supposed to go to Bill's. But he insisted on going with me instead. I know the Father's Day means a lot to Bill and he had gone out of his way to plan something for Jake's visit. So I told Jake no. I promised him I would take him and his sister out again soon but father's day, he had to go to Bill. He was stubborn and threw a tantrum. And this is where I might have been the AH. I snapped and told him I'm not his father and he should go spend the day with his real father. \n\nHe was taken aback by that, that's for sure. He locked himself up in his room. My wife was pissed at me for saying that to him (It did come out really rude) and told me I should apologize to him and take him with me. I did apologize but I refused to budge on not taking him with me. I spoke to my wife and told her how much it disturbed me to see a grown man cry out of fear. She did seem to understand. But my relationship with Jake has been strained ever since.\n\nSo, reddit, was I the AH for not taking him along?\n\nEdit: To clarify, snapping at him was not my first reaction. Most comments on how I should have explained why it was important he visit Bill, talking to him nicely, saying we can go hangout the very next day, etc. did happen before the tantrum and me losing my cool. Again, not justifying snapping (I already know I am the AH for that. That wasn't even my question.) \n\nAlso, we don't usually have joint Fathers Day plans because Bill has always wanted it to be a him and Jake event without anyone else. Long before I came in the picture. So it did not cross my mind to ask him to plan a joint day.", "prompt_sha256": "79619cd01c2128fc9143a31f51fd830f896ca5b57b924bc68d07f89debeaf822", "body_sha256": "35d85d2b342870b40834ebff4bafc3d93709ce12ad9da04161ca35ead6bdccdc", "word_limit": 61}, {"stimulus_id": "P005", "submission_id": "1dtnddf", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nI feel like I’m going to pull my hair out over this, so I thought I would post here to see your thoughts.\n\nI live in a tiny Iñupiat town, and because I work remotely and live on the same property as my entire family, I sometimes like to go for drives around town to reset my brain.\n\nThe other day, I was returning home from one of my drives, when I saw a small crowd of people on the side of the road. I saw my Grandma Mary (Grammary)’s car parked near the scene, so I started to roll to a stop to make sure she was okay. She was fine, but she was tending to one of the teenagers who lived on the nearby rez. He had fallen off his bike and he looked a bit dazed.\n\nGrammary is a nurse practitioner, and she has treated men who have been disemboweled by bears without a sweat, so I was sure she had it under control. Still, I rolled down my window and asked if she had everything she needed for the situation. She nodded and waved for me to move along. There were about 15 people there already, and I’m sure she had enough to worry about, so I didn’t hesitate to obey.\n\nAfter this, I went to my moms’ house to help them with work. I was in one of the offices, when I heard the door of the parlor open and a male voice. I assumed it was one of the new security guards my PawPaw hired until I began to hear my name. I stepped into the lobby and saw the uncle of the kid who was injured—I’ll call him Jay. He was pointing a finger at my mother, Aga.  As soon as he saw me, he shook his head and looked me up and told me I was a stuck-up bitch.\n\nI could tell Aga was ready to pummel the dude, so I quickly asked if everything was okay. I’m sure he was scared for his nephew, so I didn’t want to write him off.\n\nJay told me that I was a monster, because I just “rolled right by” a kid in need. I asked him what I should have done. Grammary was there and she had plenty of help. He didn’t give me an answer. He just said that I was the only person who didn’t stop and called me racist. I’m half-Iñupiat and half-white, so I’m seen as “less than” by the entire town. So, this was rich.\n\nAga quickly stepped in and told Jay to leave.\n\nMy family has been telling me not to worry about it. Grammary came over after her work was done and she seemed to be aware of Jay’s sentiments before we told her about everything, but she didn’t elaborate. She just rolled her eyes and assured me that she would have forced me to get back in the car if I did try to help. There were “too many chiefs” as it was. I guess I should feel better, but I still feel guilty. Should I have stopped?\n\nI know I’m missing context, but 3000 characters isn’t a lot.", "prompt_sha256": "cc9aaa975d3600a639e593392fa997442ab8354db685af52fb67b1552172ffd2", "body_sha256": "dcd921f7fd37883d98fdd4950e8aa6ea9aa7194bafb86d0070f41593fa5834ed", "word_limit": 61}, {"stimulus_id": "P006", "submission_id": "1g6ndfn", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nI'm (24f) currently at odds with Jake (24m) over this and I need some other perspectives. Throwaway and fake names.\n\nJake and I went to the beach last weekend because we wanted to go while it was still hot. I bought this new swimsuit and I thought it would be perfect for me because it would hide my insecurities. \nFor a quick explanation, basically I have a lot of stretch marks on my body, especially my thighs and hips, from growing. I have always hated them and found them disgusting so when I first found them I stopped wearing anything that would show them (shorts, crop tops, ect). \n\nAnyways Jake had told me that it hid everything fine and that nobody would see them. I believed him and I wore it. However after an hour or so I noticed them and realized that they were actually noticeable. Admittedly I ended up having a breakdown and we had to go home. When we got home I asked him why he didn't tell me they were visible and he said he didn't notice them. I knew he was lying and asked why he would let me embarrass myself like that and he said that \"they're not a big deal\" and that \"nobody would actually care if they saw them.\" There was some more back and forth between us but that was the main gist. \n\nI'm struggling to talk to him now because I feel so ashamed. It took me so long to even show him these so why would he think it's okay to just let me walk out like that in public? I do feel a little guilty now though and think I might be wrong. AITA???", "prompt_sha256": "3e4f49c16b923fb68f30def1be8b5e9995779aef717f0c722317a00f12816a04", "body_sha256": "335fb3fa4f3b3f657a974987e19b57d4e4611394e6693e3d4dca109fc59e5281", "word_limit": 61}, {"stimulus_id": "P007", "submission_id": "zkewhl", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nSo my friend of 15 years (36f) went through a bad breakup last year. Lots of abuse allocations thrown around, courts, and more. They have a child together, never married, he made all the money when they were together as she has never worked a real job. I (35f) work a full time job and have been in my industry for about 15 years. I now work at home since Covid. Married for almost 10 years and has 2 children. One the same age as hers. \n\nThrough this breakup I was there for her every step of the way. Had her and her daughter over to play all the time, went on play dates with our other friend and our kids, hooked her up with a friend of mine to make some $$$, and emotionally supported her through all of this. \n\nAll of sudden she is back with her boyfriend and now has a job at a place in the mall. Which is so great for her. Now that she has this job she is very busy and can’t hang out as much as before, which it totally get. I worked a job like this when was 19 before I got into my career. I know how demanding retail is. \n\nRecently it was our mutual friends birthday and she invited us out. Initially I was going but came down with covid and couldn’t make it. So I text our group chat to see when the 3 of us could go out and celebrate. My friend said she couldn’t go because she had to work. Which I already expected her to say so my other friend and I went out without her. \n\nThis is where it gets weird. She was PISSED that we went out without her because she couldn’t make it. About a month later was my birthday. I text her to see if she wanted to go out with us and she responded that she had to work. So she didn’t come. \n\nAll of a sudden she removes me from following her on Instagram and text me that she can’t believe I didn’t invite her to my birthday and I sent her a screen shot of her response (which she didn’t even acknowledge) and she then told me we can’t be fiends anymore because she has a job, a child and responsibility’s and I’m out all the time (which is not true at all, I went to dinner and out for my own birthday) and doesn’t get to work from home. Then removed me from following her on Instagram and blocked me. \n\nTruly have no idea what I did wrong besides live my life. AITAH?!", "prompt_sha256": "4464bafefecdb83a0562c898517c393f29cc1782683198538dcd5f6c502d0bbb", "body_sha256": "00bfd90b994766c7b0b174c05fcaee015f7e6c3f8adcfc1cb9617bbafba39dea", "word_limit": 61}, {"stimulus_id": "P008", "submission_id": "go7u8k", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nI (25m) and my gf (24f) live together in a small apartament since 2 years. I work part time at home right now due the coronavirus pandemic and I keep studying music, for this reason she and I have now a lot of time to talk about life stuff, and her favorite topic is talk about babies and kids. It scares me because we're very young and I don't feel ready to be a dad. \nShe has been bringing the topic daily for weeks and I told her we would talk about it maybe in a pair of years, because the apartment is small and most of our income is meant to pay bills and maybe a future bigger apartament, or a house. And my gf actually is jobless.\n\nI asked her politely to not bring the topic so often but she ends bringing it everyday, making me so uncomfortable. My gf is kinda shy and sometimes has a childish behavior that I find cute, but this topic is something serious and I fear she getting pregnant right now, because she jokes about it and sometimes seems like she really wants to get pregnant \"accidentally\". \n\nSo 3 days ago, she joked again about it, I was reading a book and I told her I don't want to talk about babies anymore and that I wouldn't reply if she brings the topic again. \nShe said okay, and then said she already knew I disliked children (false), and that we probably couldn't stay together in a future. It literally felt like a kick in the balls. \n\nAITA?\n\nEdit: well guys, I talked seriously with my gf and she said she has been joking about this and that I can trust her. She said she wants to start a family when we move to a better place and when I feel I am ready. I checked the condoms and she takes the pill in front of me. All okay.", "prompt_sha256": "0f97fc0bfd453031e088fba1ebcb09f3284b30f5b57f6d8397e59b29f887de0d", "body_sha256": "34289988f160c0abd9614cf7634a1262a6ca38f16f3afdabd7d3af84bf45e0cb", "word_limit": 61}, {"stimulus_id": "P009", "submission_id": "npuxdd", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\n\nA week or so ago my cousin took in her 5 year old niece who would be in foster care right now if it wasn’t for her taking her in. Without going in to too much detail, she’s had a rough time lately. \n\n\nSo they show up at my daughter’s birthday(6th birthday) to drop off cousin’s bio kid. Cousin didn’t want to overwhelm niece since she’s not from our side of the family and doesn’t know us so she didn’t plan to stay. But she gets there and the little girl wants to stay! Yay, glad we could make this little girl feel welcome. But she has no swimsuit and everyone will be swimming. No worries, my daughter has plenty of swimsuits. This girl is quite bigger than my daughter but we manage to find the newest one we bought for my kid. We sized up so she could grow in to it so it fits the other kid perfectly fine, a little snug even. \n\n\nThis causes my daughter to spiral. It was her brand new bathing suit so she wanted to wear it on her birthday. I totally get that but at the same time, I want to raise my kid to know things don’t always work out the way we want even on our birthdays.\n\n\nThis results in a full meltdown where I end up saying my daughter will be spending the rest of the party in her bedroom alone if she doesn’t stop this nonsense. I explained why we needed to be kind and let others use her swimsuit but she was being stubborn.\n\n\nThis led to a heated discussion with my mom about being “so mean” to my daughter on her birthday. She said every kid should be able to get what they want within reason on their birthday and this was totally within reason.", "prompt_sha256": "9b4f27c7791c6b76a48f7e469222270829a819826fc0275fe75d72c1190e884c", "body_sha256": "d023adcaf398bc0eadd6cd28e7e021c088bda431a36e254487d83f3a85d60412", "word_limit": 61}, {"stimulus_id": "P010", "submission_id": "ufafmx", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nMy (25F) life growing up wasn’t perfect at all. My parents always favored my sister, Emma. They treated her as if she was the perfect daughter and treated me like I was a stranger in their house. They never had a good word to say about me. Emma was the most amazing daughter in the world, while I was the annoying one who tried to hard. It’s safe to say most of my childhood was spent trying to please my parents. When I turned 17 I moved in with my grandparents and went to college. My parents didn’t even put a penny in for me to go to college. I didn’t really talk to my parents through college or after. When I got pregnant I only told a few family members. One of my aunts ended up finding out and told my parents. I was immediately showered with gifts and texts from my parents telling me that I should come back home (I moved to a different state after college) and that they miss me. My sister even said that she wanted to be in my child’s life. I later found out that my sister was infertile, meaning she couldn’t have kids. I was a little disappointed to find out that my parents didn’t want to be in the baby’s life just to be good grandparents but for the fact that my sister couldn’t have any kids. So they made me the second choice again. I didn’t want my baby to have grandparents who only wanted to be in her life because her aunt couldn’t give them a baby. When I had my baby I told them that I didn’t want them in her life. They were extremely mad and said all these things about my baby and me. My husband thinks that I shouldn’t accept them into my baby’s life. I agree. I’m getting messages from my family calling me an asshole.", "prompt_sha256": "6cb638cf4c05ca3116e05ce8bf2cead790ac9e0e15f2a751596bc09757207c8f", "body_sha256": "e457b92282d79decc90c9805a8dff5ae4cecb98deb5fa593c4f93d57070f7e3f", "word_limit": 61}, {"stimulus_id": "P011", "submission_id": "ptqxea", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nHey guys, thanks for all the love and support. Unfortunately I can’t reply to all the kind people who commented here but here’s a summary of what happened. I sat her down and told her that her brother and family members aren’t allowed in our house if they try to push me one more time. I told her I’ll call the cops on them for trespassing since the house is mine. Also i spoke to her about helping more around the house like a good partner does(she just never did because i never asked her to tbh). I was very firm about it all and all i heard was sorry afterwards. I think that over the years I just let them push me into a corner and they thought i was gonna let them do this too but this backfired.\n\nThey apologised and said they’d never bring it up again. \n\nThrowRa \n\nMe(m33) and wife (f31) have been married for 8 years and have had a great marriage. Her family is amazing to me. I am an orphan but they treat me and respect me like their elder son.\n\nWe had twins few years ago and after a lot of discussions, I decided to be a SAHD. She earned a lot more than me and didn’t want to be home so I took that role. I was okay with it because it was for my family.\n\nI’ve always done all the house chores, taking care of kids, cooking, shopping and etc on time. Our marriage hasn’t struggled at all.\n\nMy wife has a younger brother (26m) who is on spectrum but is high functioning. When I say “high functioning” I mean in playing on his ps5 or some other games. He’s come to visit us a few times and I’ve always had to clean up, cook, clean his laundry/dishes and tell him to take showers.\nLast week he told my wife he wanted to move in with us because he didn’t feel like living at mom’s house anymore. My wife said yes without talking to me. just 2 days ago she came upto me and said “oh he’s moving in with us, sorry I forgot to tell earlier”. I said no, I don’t want him to move here and we had a huge argument about it.\n\nI adore the guy. He thinks of me as his big brother and respects a lot but I already have twins to take care of and the house. I can’t be running around after him too.\nMy wife says that I should just teach him things and he’ll be fine but I don’t think it should fall on me at all. I would’ve loved to help and all but before we had twins. I still told her that I don’t agree with that decision and she should speak to him about it.\n\nShe and her family thinks I’m being harsh AH and it wouldn’t be a big deal if he moved in since my wife makes all the money. \n\nAita?\n\nEdit: I said “high functioning” because he used to  take care of himself, drove a car and many other things but over the years he just slowly stopped doing things. Now all he wants to do is play games and watch tv. I thought it was bad and he needed some help but his family just taking care of him like a child and here we are now.\n\nEdit2: i had a lot of time to think so I decided to tell her that no matter what, he’ll not be allowed to move here and if her parents have something negative to say about me, they won’t be allowed to even visit my house. I’m not gonna let them push me into a corner like that.", "prompt_sha256": "31826cb9f93936c78fdf6fd8c4e043a514cae0f0fb23438cd12858ab24a8e092", "body_sha256": "e66b9af19dcb2fe3537894c8781fa9223829fc7d5df3f0c13c9940e5bfdccb89", "word_limit": 61}, {"stimulus_id": "P012", "submission_id": "w32gs1", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nMe (23M) and my girlfriend (19F) have been together for a few months and her parent’s invited us both round today. It was the first time I’d been her parents’ house, so she’d warned me to be on my best behaviour as I’d be meeting her extended family, which didn’t make sense to me as I’m always polite and respectful (in fact, my girlfriend is usually the one to make a scene but I digress). \n\nMy girlfriend told me her younger brother was having a pool party so I’d worn swimming trunks instead of shorts because I assumed everyone would be allowed in the pool. The day started off well and her family and I seemed to get on amicably with her family despite a few weird comments about my profession everything seemed to be going swimmingly (pun intended). \n\nAfter we sat down I asked my girlfriend when we’d be going in the pool and she looked at me weirdly and told me she never said we would be going in the pool. For reference it was the hottest day in England on record (40 degrees C, around 105 freedom units) and since I am slightly overweight and have high blood pressure I can get quite warm and sweaty which was making me self-conscious. I told her this and she said I was being childish and I should just go inside if I was so warm. She seemed angry and stormed off. \n\nThere was still nobody in the pool at this point so I decided to just quickly take my top off and hop in to cool off. I felt much better imediately and was feeling quite relaxed however her family members kept staring at me and it was making me uncomfortable. I saw her brother walking around the pool, looking at me confused but as he didn’t say anything to me I didn’t think anything of it (for reference the pool is quite small so couldn’t fit many more people). \n\nI heard him whining to his mum about wanting to go in the pool and a couple minutes later she came over and firmly asked me to get out. I was confused and honestly a little astounded. I got out anyway because I wasn’t wanting to cause any problems as I like to accommodate people’s needs but everyone after still seemed to be acting weird with me. We left quite soon after this as the atmosphere was quite tepid and I told my girlfriend I was really uncomfortable because it felt like her family didn’t like me.\n\nMy girlfriend didn’t speak at all in the car ride home but when we got home she said I embarrassed her in front of her family and that I was acting super immature. I said that she implied that we’d be going in the pool and that she knew about my health issues so of course I would use the pool. She got pissy with me and hasn’t spoken to me since. It’s quite awkward because I’m currently staying at her flat.\n\nSo Reddit am I the asshole? I thought I could use a pool which I was told I could use.", "prompt_sha256": "59fb8de1ebe2cc31d833dae6a6a39e53bbafff2a70b16e535cc5f0818a057ba0", "body_sha256": "0d1d68296910ab4f0bb510708fc11bb9146ec769d180379cce51620e2589073a", "word_limit": 61}, {"stimulus_id": "P013", "submission_id": "re5n23", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\n\"Elmo\" is a former friend of my husband that hates me with the passion of a thousand suns, he tried for years to get us to break up but when it didn’t happen his hatred grew even more. I am unsure why he disliked me initially but I know a big part of it is because our birthdays are very close and my husband has always prioritized mine. He was always rude and condescending with me, would speak over me, the whole shebang. It was an issue for my husband since he defended me at the beginning but then I just told him to ignore it, I felt bad for Elmo because my husband was one of his very few friends. \n\nIt all exploded when we announced our engagement, Elmo was upset and let everybody know that I was just trying to trick my husband into marrying me because I was a social climbing gold digger. (Side note, it would be the other way around but Elmo didn’t know that then.) Needless to say he wasn’t invited and my husband said it was too much to keep ignoring it. They still sometimes see each other due to a pair of common friends, we would feel awful to request them to cut him off because that is now the extent of his social circle. I mean, he knows people but is not exactly liked around.\n\nLast night, one of the common friends had a pre holidays party and invited us. Since my cousin \"Ricky\" is visiting I considered staying home or doing something else, but the organizer said he was welcome to join if he wanted. Ricky is gay, not a big deal for most but it seems Elmo is not a fan although in Elmo’s defense he might just dislike anything that has to do with me and not be homophobic but god only knows with him. We were there already when Elmo arrived, he was really happy to see my husband and began making small talk with my cousin when he saw me and made a face, I simply shrugged it off and just greeted him to be polite. Fast forward an hour or two, Ricky talks about his ex and how he misses him but doesn’t think is the right time for them. \n\nElmo interjects and says maybe he, Ricky, is just wrong. I look at him like wtf, Elmo says \"I’m just saying he should let people know he’s gay before he gets close to them\" Everybody was looking at us now and I just did a *clutches pearls* hand movement and said \"OMFG, the audacity of a gay person shaking hands with a straight one\" People laughed and I just rolled my eyes and went to the kitchen for more wine. Elmo followed me and said it was uncalled but he didn’t expect anything else from me. I told him is not my fault he is a homophobe and probably a closeted gay in love with my husband. He screamed, I laughed and said \"at least now we know why you hate me\". \n\nWe left and I apologized to the hosts but told them I couldn’t stay there. My husband found it hilarious and doesn’t care about Elmo anymore. The host sent me a text apologizing for the drama, reminding me it‘s not my fault. But my cousin feels calling him a closeted gay was uncalled for and if he is I just made it all worse.\n\nAITA?\n\nOh, Elmo is 43 btw.", "prompt_sha256": "adf581ca6a052be177208ae97cf9099264a012bcd398601670ae14282b21dcb1", "body_sha256": "62705f15810839d0dbc7b47bf2de4978aab21748e4d2d01159e71d4bf33b0519", "word_limit": 61}, {"stimulus_id": "P014", "submission_id": "oheeim", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nThis is my throwaway account. And English isn't my first language, so excuse my mistakes.\n\n\nFew days ago, I got a call from unknown number and it turned out to be my dad's friend who isn't VERY close to my dad. He talks with my brother (I guess) and got to know that I'm planning to study abroad after finishing College in my country( I did call my brother after that and gave him an earful). It seems like he wants his daughter to study abroad (Just for name sake) and wanted me to decide on where I'm going and what I'm going to study  so that he can send his daughter with me to study together. He also mentioned her daughter doesn't mind whatever course I pick because she isn't into studying that much and just wants to have some fun.\n\nFyi, I still have one year left till I complete my college and I haven't thought of next step even though it's time for me to start preparing something like GMAT,IELTS/TOEFL.\n\nHe offered to send me videos and info about different courses which I didn't want to initially but since he compelled me, I thought he was just trying to help and it wouldn't hurt to learn more about programs which might suit me. \n\nThen, He started to call me everyday (2-3 times per day, I ignore sometimes)and asked if I made my decision. Again, I guess I have enough time so I didn't want to finalize yet.  He also started to convince me into Counseling services and much more stuffs which I wasn't interested in. I politely told him that I'm already consulting someone else and I'm not interested in what he is sending me. Soon, I felt like he was pressuring me and not helping actually. So I decided not to take his calls and respond to any of his texts. \n\nInstead, he called and told my dad about everything and asked him to make me make decisions soon. My parents aren't pressuring me (which is a good thing, since I get anxious very easily and he's making me very anxious, which Is another reason why I'm avoiding his calls) but my dad is wanting me to talk to him again just to escape his calls. If I don't pick up his calls, he instantly calls my dad and talk for a long time(which annoys my dad too but doesn't wanna say). \n\nMy dad wants me to deal with him myself. Mind you, I haven't even talked with him before even though he claims that he came to my home one time( maybe I forgot) but, still it doesn't give him rights to talk/ pressure  me like this.", "prompt_sha256": "ccd8a1adb62dfd37f817a1d4a58e56c48a7855c657cc6d7d1760023a2b5ccb0a", "body_sha256": "6d71394b0796f973d27cd3e1f1aa5cf6a8f4e3419da60108542eac9943c52849", "word_limit": 61}, {"stimulus_id": "P015", "submission_id": "f4s1kv", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nMy wife dropped my sister Carly's phone in the pool. It still works but Carly has been demanding that we (well my wife) buy her a new phone. I think it's a reasonable enough request except....when the incident happened, Carly yelled, swore and threw a flip flop at my wife in rage. I've refused to buy her a new phone or \"let\" my wife do it either (I've been acting as intermediary) until she apologises. My wife just wants to buy it and get it over with. \n\nAITA for refusing to budge?", "prompt_sha256": "77f4da06d5e3f6f39f37ee71fff18b74cb6b80a7e89a21f54003c612603a9e29", "body_sha256": "acb30af54bcb2b15148483412f3f06fc05434f1511c04a4ec71311778bee8746", "word_limit": 61}, {"stimulus_id": "P016", "submission_id": "15p8o1j", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nMy (28m) wife (26f, Jenny) and I are housesitting for my parents for two weeks while they are on vacation. They have a big house with a pool and a dog, and it's a nice change of pace from the apartment, so we were happy to do it.\n\nI had to travel for work for two days this week, so my wife was alone at the house. I got a text from my dad on Thursday afternoon, saying \"might want to give Jenny a heads up the pool guy will be at the house anytime this afternoon.\" I said \"ok\", and he said \"might want to tell her, like, now.\"\n\nIt was a confusing message so I texted Jenny to give her a heads up, and she just said \"omg ok funny.\" It was all weird so I called her, and she said she was swimming and laying out with nothing on (it's a private yard).\n\nI immediately texted my dad and asked how he knew Jenny was in the pool, and he said he and my mom were checking the house cameras and saw her. I let him know I thought it was odd they checked the camera and saw her naked, and that they basically let me know they saw Jenny. They think I am completely missing the point, that they were looking out for her.\n\n(I told Jenny that they had checked the cameras and saw her, and she was completely unbothered, said she figured, and appreciated the heads up. I asked if it bothered her that they saw her and she said I am totally overreacting.)\n\nAITA for calling out my parents for this? ", "prompt_sha256": "0c6394e2544d3ab4a7ff741d5cbd3c1d3e4c1aa96d03830fb299a3dec619629c", "body_sha256": "75551329cb9be0350bb1965e5c58c7a5d3c3fd8d9131169405eed2a2d55d24ca", "word_limit": 61}, {"stimulus_id": "P017", "submission_id": "10ukzpr", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nrecently, my friends and i went to a restaurant for dinner, where i noticed there was a cute waiter that was serving us. i told my friends, not thinking much of it.\n\nthroughout the whole dinner, they proceeded to embarrass me about it, sometimes around the waiter, even asking to take a selfie with him. at the end of the dinner, while waiting for a friend to use the restroom, i noticed a friend of mine talking to the waiter 1v1, and i panicked, worried they'd embarrass me again but worse. i left (the bill was already paid for atp) and waited outside for them.\n\nthey all come out smiling and laughing, saying they told the waiter i thought he was cute, and they got his number. i felt beyond embarrassed now.\n\nthey put his number in my phone, and i said fuck it and sent a text. i wasn't expecting much to come out of this, so i was shocked to see him reply. we continued to talk throughout the night, even after my friends and i parted ways.\n\nthe next morning, i was happy, the waiter and i were having a good conversation the same morning.\n\nlater at lunch, my friend confessed that it wasnt the waiter that i was texting, it was my friend. my friend group was in on it, and even made a groupchat to laugh at me behind my back, leaking the messages and such.\n\ni was so mortified, they told me in front of most of our friend group (as i went to dinner with only 4 of them)\n\ni angrily left, sending a message to our discord server saying \"fuck you guys\" and went off on them.\n\nthey thought i was upset at being catfished, and while i am somewhat upset, i was mainly upset for being turned into a joke and laughed at behind my back by people who i called friends. 2 of them were my best friends.\n\nsome of them had said im overreacting, and some say im making it a bigger problem than it needs to be. my family says i should drop them, but idk what to do. some people say im right for being upset, and im not overreacting.\n\naita?", "prompt_sha256": "ad755988f3bd40370d157bcd91c71b968141334c3de8840ed6443c05b5002d2f", "body_sha256": "2296ff16cac8cef4dbbcfdfba6de523c2e27631f7b320cf1b68da69601f06c18", "word_limit": 61}, {"stimulus_id": "P018", "submission_id": "1ehrxfr", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nSo, the title might make me sound innocent enough, but let me give you the full context before you decide.\n\nA while back, my workplace was going through a particularly stressful period. Everyone was on edge, morale was low, and the tension was palpable. In an effort to lift everyone’s spirits, I came up with a light-hearted idea: a quiz to match each of our team members to a character from Winnie the Pooh. The idea was that everyone could anonymously vote on who they thought would be the best fit for each character—like who would be our Christopher Robin, who would be Winnie the Pooh, and so on.\n\nTo my relief, the plan worked like a charm. The quiz brought some much-needed levity to the team, and people seemed to genuinely enjoy it. I left the quiz open for a day to give everyone a chance to participate, and the next day, I published the results in our group chat. The feedback was overwhelmingly positive; it felt like everyone appreciated the fun distraction.\n\nRight after that, I took a week off work. During that time, I was actively job hunting and ended up securing a new position. When I returned to work, I handed in my notice.\n\nA few days later, I was unexpectedly called into a meeting with HR. To my surprise, I was informed that one of my colleagues was deeply upset about being voted as Eeyore. She had reportedly told HR that during a previous training session, we had discussed Winnie the Pooh characters as metaphors for mental health. Although I don’t recall having this conversation with her—especially since I didn’t attend many training sessions with her—I was now being accused of making a thoughtless, hurtful association.\n\nHR then told me that they were considering disciplinary action against me. However, because I had already resigned, they decided not to pursue it. But they made it clear that if I chose to retract my resignation, they would proceed with the disciplinary process.\n\nFast forward to my last day at the company. At 8:43 a.m., I posted a heartfelt goodbye message in our team Slack channel, expressing how much I’d miss everyone. I also mentioned that my 15-year-old stepchild had drawn a picture of Eeyore, which I included as a parting gift for my colleague. To me, it was a thoughtful gesture; the drawing was beautifully done, and I thought it would be a nice touch.\n\nBut less than an hour later, at 9:20 a.m., I was called into another meeting. Apparently, someone had filed a complaint about the Eeyore drawing, deeming it \"inappropriate and insensitive.\" The situation escalated quickly, and I was promptly escorted from the building.\n\nNow, Reddit, I’m left wondering: Was I really that out of line? AITA for sharing that drawing of Eeyore in my farewell message, or was this an overreaction on their part?\n", "prompt_sha256": "083b800e6c57532361d959d4bf7095767da04f4ebe879bc30d67d8dfe175745a", "body_sha256": "3d921510ee5b51a07b1b4bb123f767fc7b425603df0ddcdc8f780bbba7102036", "word_limit": 61}, {"stimulus_id": "P019", "submission_id": "16cn4cy", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nMy GF (29F) and (33M) have been together for 3 years.  I bought a house a year into our relationship and she moved in with me about 9 months ago.  She has lived in apartments her entire life so she was extremely excited to have actually have space and a yard to call her own.  My house had an existing fenced-in garden area that the previous owners had let go into disrepair.  I am not a green thumb by any means, so I didn't do much with it either.\n\nWhen my GF moved in, she wanted to get the garden up and running again, so that was our Spring project.  We cleaned everything out, tilled the soil, and set up a few raised beds for veggies and herbs.  But my GF also wanted to get chickens.  I was hesitant to agree because I have a dog who I let out into the backyard and I don't know how he would react to chickens.  But instead of just saying \"no,\" I told her we need to look up ordinances and laws first and go from there.\n\nWithin hours she had found all the city ordinances and laws about backyard chickens and showed them all to me.  Apparently, we can have 3 chickens (no roosters) in their yard.  I told her she can have 2 chickens, but she has to pay for everything related to them and as far as I'm concerned, they are her pets to care for.  \n\nSo, she bought a coop with a fenced run area (that I had to assemble and set up heating), and we put it in the garden so that my dog could still have access to the yard without harassing the chickens.  She started letting the chickens out of the coop so that they could roam the yard (she calls it free-range), and after some introductions with my dog, they seemed to get along fine and my dog leaves them alone.  \n\nHowever, I didn't know how much chickens poop.  It's everywhere.  If you don't clean it up every day, it's everywhere.  With my dog, I go out there once or twice a week and pick up after him because he only goes in 1-2 spots.  But the chickens poop literally everywhere they go and you have to keep up on it much more often.  I complained to my GF about it multiple times and told her she needs to either keep them in the garden or clean up after them every day but she usually only does it when I pick up after my dog, or sometimes I just end up doing it.  \n\nShe won't keep them in the garden because they peck at the veggies and herbs.  She won't keep them in the coop because \"they've become accustomed to free-range and it makes them happier\" according to her.  \n\nWe had another fight about it the other day because I stepped in chicken poop while wearing sandals and it's gross.  I told her if the chickens are going to be in the yard, then she needs to pick up after them every single day.  She told me it's unreasonable to expect her to walk the entire yard everyday cleaning up poop when I only clean up after my dog twice a week.  \n\nI told her she either cleans up after them every day, keeps them in the coop or garden, or they're gone.  She thinks I'm being an AH about this and that I hate her pets and just want them gone.", "prompt_sha256": "62e05dc364af9749e4134be9d0d175e4f5fbb5d3fe8dcbffbc89e45ae4cf671d", "body_sha256": "17af7c002786469617433e2e4261d109ab77ed4d571c519c2bb02d14dc286409", "word_limit": 61}, {"stimulus_id": "P020", "submission_id": "156vlun", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nI was hanging out with some friends at the local park in the neighborhood and since I’m not so sporty, I decided to go to one of the friends’ house to chill with his younger sisters instead. While at their house, I had to take a shit pretty bad. Shitting in the girls’ bathroom felt a little wierd so I decided to go to the one next door in my friend’s room. \nWhile shitting, my friend comes home from the park not knowing that I was in his bathroom. I don’t remember exactly what was said, but he wasn’t okay with it. Once I was done, he had already left the house to go back to the park. I ended up going back too and when I did, it seemed like he was ignoring me. I sincerely apologized to him, but added that if our positions would be swapped, I would be fine with it. At one point, he told the other friends that all but one of us should go to one of their houses to chill there. Obviously offended, I apologized again, but he didn’t care. The other friends seemed to side with me a little, telling him to just let me come. I ended up just walking home to avoid further drama. \nI told my mom about the situation and she sided with me. A couple of days later, my parents went out with my friend’s parents for dinner. My mom went out of her way not to bring up the shituation, but when my friend’s mom brought it up saying that her son told her that he had asked me not to shit it his bathroom many times and that I was ignoring his requests, my mom “exploded.” \nWe would usually wave to each other in the halls or just say “hi,” but he was still ignoring me. I did catch him off guard a couple of times with a 😮 and managed to get a 😮 back from him, though.\nMy brother ended up talking to both of us and helped us get over it, and all is well now, but AITA for shitting in my friends bathroom?", "prompt_sha256": "b4afa29f849dcaaa62e01e7239d3ddb8066412a4d40eb113ce7185406ce5c190", "body_sha256": "f1fa23fa949b97a2ec03938683aaceea7df6b8002731b963e66d44e24cf50563", "word_limit": 61}, {"stimulus_id": "P021", "submission_id": "hs2g2e", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nEDIT: As a follow-up to several comments, AITA if I value my own comforts (having a chill work schedule, time to pursue hobbies etc) over being in the same city as my girlfriend? I would 100% rather be long distance and be happy in my own life than be in the same place and be miserable with something external to the relationship. And in this situation, there was no way to have the lifestyle I wanted and be in NYC with her\n\nEDIT: To clarify about my girlfriend \"forcing me\" - She just nagged at me and said long distance would be hard on her. And she would always bring up that she did the same for me, because she stayed in NYC for her intern year while I was finishing up med school. But I never asked her nor cared if she wanted to go elsewhere. Essentially just a ton of emotional pressure and occasionally tears.\n\n\\--\n\nMy girlfriend \\[26F\\] and I \\[30M\\] have been together for 5+ years. We are both in residency and she is one year ahead of me. I just started earlier this month and am going into radiology which requires an intern year in general medicine before actually starting radiology. Usually people choose the easiest intern year possible because the year doesn't really matter for your career. When I was applying for intern year, my girlfriend who was already in residency, basically forced me into only applying for places near her in NYC. I didn't really want to do my intern year in NYC where all the programs are known to be ball-busters and now especially COVID, who wants to be here? But to keep her happy (and tears at bay), I complied.\n\nFast forward to now, 2nd week of my intern year, and I am hating life. I am working atrocious shifts at the hospital, wearing the most uncomfortable PPE, and don't do anything other than work and sleep. I have buddies at those \"cush\" programs elsewhere in the country and it doesn't help to hear them sleeping in and getting off work early. Some are just working from home entirely.\n\nI feel myself getting very resentful of my girlfriend for forcing me into such a miserable program and have been more and more short with her. What was the point of making me stay in the same city as her if I'm going to be working all the time and won't have any time to spend with her anyways? She tries to be understanding but will ultimately ask why I don't love her enough to sacrifice to be with her. She'll also say that she made the same sacrifice for me last year for her intern year even though I never asked her to and would have been fine if she went somewhere else and we were long distance for a few years.\n\nAm I being an asshole about this? I just feel that this year together will do more harm than good for our relationship.\n\n**TLDR:** Girlfriend forced me into a miserable 1 year intern year just to be in the same city as her and now I'm starting to hate her", "prompt_sha256": "2ada6a20dd3251263236b4ad40a405d2e262c723cc1d2c6b408d897d979c3f24", "body_sha256": "ec2edab50e98bd36025f0c11be0d775a324f32c7e583cf46d9ce43daddb42fc0", "word_limit": 61}, {"stimulus_id": "P022", "submission_id": "1eafp0i", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nI 34f was away with my husband and 2 children we also went away with his brother and his family (wife and 2 kids). On the first full day of our stay we went swimming at had a great time! The second day I wore a bikini instead of a 1 piece bathing suit. My sister in law asked me to put my other bathing suit back on but it was still a little damp and I didn’t want to feel uncomfortable. She told me she was uncomfortable because I was “exposing myself to her husband and children” I told her bathing suits are very normal to see in public and that if she’s uncomfortable it’s her own issue. She has since gotten out husbands parents involved and the mother is saying it was fine that I wore the bathing suit and that she’s over reacting and the father thinks that I should have been more covered. ", "prompt_sha256": "4356633c32b7a862ac53eef42cf1d54d7039076dfff505d00dacf83480cb597e", "body_sha256": "0e988621ec6e6fc0a2b3133950e2938b36d940224f25576868d902c4c147ec61", "word_limit": 61}, {"stimulus_id": "P023", "submission_id": "12eivy7", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nTL;DR\nMy husband throws his dirty clothes on the side of his bed instead of putting them in the hamper right next to his bed and expects me to pick up his dirty clothes and wash them. I’ve asked him several times to put his dirty clothes in the hamper if he wants me to wash them but will only do so once a month when it’s a bunch of clothes. \n\nWhole story\nMy husband (31M) and I (32F) were talking about this last night as I had a load of laundry going in the dryer when he got home from work. He thinks I’m wrong for not doing his laundry that he leaves on the floor. \n\nI started doing his laundry 3 years ago when we bought our house. Before that, we rented a place and did our own laundry. Because he wanted his clothes washed a certain way. But when we bought our house he asked if I could just wash his clothes with mine and I agreed. \n\nAt some point, he started to just wear his boxers to bed and would throw the rest of his clothes on the floor. When I noticed that he would just throw his clothes on the floor next to his side of the bed, I asked him to start putting his clothes in the laundry hamper in the master bathroom. He complained that it was too far and that he just takes his clothes off when’s he’s getting into bed. So I bought him a hamper and put it right next to his side of the bed. I thought problem solved. \n\nTurned out, I was wrong. He just throws his dirty clothes around the hamper instead of putting them in the hamper. I asked him to start putting his clothes in the hamper next to his side of our bed and he complained that it was too dark to see. But he doesn’t have a problem placing his phone on his night stand. I told him I won’t wash his clothes if they are on the floor. Only if they are in the hamper. So he started putting his clothes in the hamper for a couple of weeks. Then stopped. So I stopped washing the clothes that he leaves on the side of the bed(only washing what made it into the hamper). Then he got mad at me for not washing his clothes and asked me to start washing them again. I told him I would wash them if he put them in the hamper. I feel like this is a simple request. I’m doing him a favor by washing his clothes. Even if he doesn’t put them in the hamper right after he takes his clothes off, he could put them in the hamper in the morning when he wakes up. Or before he leaves our room each day. \n\nI do wash whatever he puts in the bathroom hamper. He doesn’t have a problem putting stuff in there but it’s usually only a few items. We both have full time jobs. I work remotely from home. I do the majority of the cooking and cleaning. Bills are split 60(him)/40(me). He makes more money and wants me to be able to save money for a rainy day so he agreed to pay more bills. No kids yet.", "prompt_sha256": "41e8933584dd7c1bb3049c806a027de0b6f38c3f9ee57f8979bf04b1340b2dc5", "body_sha256": "e32c9b8e88c96d837ee87cb9369ad76fee76a04569dd046c67b9fa9bc7ada6f5", "word_limit": 61}, {"stimulus_id": "P024", "submission_id": "1i4658l", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nMy friend and I were hanging out at my place for almost the entire day yesterday. I told her about this amazing ice cream place at the mall and I'd treat her. At first she agreed and told me it's a great idea. Then she suddenly snapped and said that she can't eat ice cream because she's on this healthy diet, and she absolutely will not touch that stuff and it's wrong. I told her that she's not forced to eat it, that it was just a suggestion.\n\nIt just so happened that my work place (it's at the mall) needed my assistance and asked if I could come in for a few minutes to help them. (I live like 5-10 mins away from the mall so it's no problem). I told her we any ways have to go because my coworkers need help.  I told her we can hang at the mall for a bit if she's down. Any ways we were passing the ice cream place and I told her I'm grabbing some for my self and I asked her if she's sure that she does not want any. She said she's good and thanked me for offering.\n\nWe're browsing the mall and she tells me the ice cream actually looks really good if she could have a lick. I told her if she really wants it I'll get it for her no problem. But she said she just wants to try it from mine. I told her I'm not comfortable with that but the offer still stands about me getting her an ice cream. She got annoyed and said \"Why are you being such an AH about this I don't want a whole damn ice cream I just want a lick from yours\". I told her again I'm not comfortable with that.\n\nI'm just very weird when it comes to sharing food where spit could easily be exchanged, unless I'm very close with the person and I'm at a certain level of trust with them for example my mom or my brother. Like I could be good friends with some one but still not be comfortable sharing those types of food with them.\n\nMy friend and I are just good friends from college that is all.\n\nSo AITA? I mean I still offered to buy her an ice cream as an alternative.", "prompt_sha256": "189f260dd4d54af67483fd81cb8c7ca5f32944c43a9a9a1bc5741d2a789ad0ee", "body_sha256": "0e329a021a8a72c1cb24a35d4f641c5efbc178e27844a8277339795174508d45", "word_limit": 61}, {"stimulus_id": "P025", "submission_id": "vca6z1", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nMy 21 yo daughter, part time engineering student, living at home, no job.  She’s a good kid, good student.  It’s tough getting her to do anything around the house to help out.  She always gives attitude when reminded to do her weekly chores or is asked to help out.  says she’s so busy with school, so stressed out, etc and huffs and puffs while doing what is asked of her.  She hasn’t gotten job since high school because she is so busy with school ( mind you, she only had three classes this semester).    But she’s recently engaged to a wonderful young man and she ALWAYS has time for him, his family or her church activities.   And fiancé is at our house every day.  If she’s home, he’s here.    I cook most nights of the week, (and I despise cooking).    She and fiancé stay in her room and come out to eat and then back to the room.   No help with dishes or cooking or anything.   So recently I said to her, hey, at least pitch in every now and then.   And, maybe switch it up, you know sometimes eat at his parents house.   Because with a wedding this year, two kids in college, plus my youngest rodeos (which is hella expensive), money is a little tight and I’m not keen on adding an extra mouth to feed every day.  My husband thinks I’m the AH for saying something about the fiancé eating here every day.    And I do feel like an AH.   What do y’all think, AITA?", "prompt_sha256": "2c39f4b27d3b5ffad72e5770b0497f9e133d0fac8a0472ad20e87bf0eb53177d", "body_sha256": "865a4b40f731d98f33397934f235d6b9777b4ff8774f71ec59e3cb2c4d0e255f", "word_limit": 61}, {"stimulus_id": "P026", "submission_id": "y68ihz", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nSo my MIL is going downhill fast. She's been in ill for several years now but due to a heart attack they've changed her medication so now her BP has sky rocketed and she's had several falls.\n\nMy husband promised his dying father that he would look after his mum. He felt better placed to do this as at the time he was single and his sister had teenage children.\n\nNow he is married, and we have 4 small children. \n\nHis sister has been down this weekend (lived 4 hours away) and would not hear of MIL may need in the not to distant future to go into a home/assisted living because my husband had promised their father, and that I need to get back in lane because I'm not really part of the family (that's a whole other story) and what difference does it make if for the time being my husband leaves me with the children and moves in with his mum to keep her out of a home. Because he promised his dad.\n\nI tried to point out that SIL knows how to play my husband...and will continue to use a promise he made as a young single man to enforce her will on him...she's not offering any help. They were here this weekend, and so husband came home for the first time in a month to spend the night with me and the children. She didn't do anything to help his mum up to bed and got grumpy when MIL woke her at 11am to help her down so she could get herself a drink and food. She didn't want to call my husband because she's very aware that he's spent very little time with the children or me and wanted us to enjoy it.\n\nShe was considering moving into a home, but SIL told her not to allow my husband's selfishness to force her to do something she doesn't want to do.\n\nWhenever husband starts arguing with her she brings up his promise to his dad.", "prompt_sha256": "c74dc3b7fc3f49b036f1a96830a31657876a3d44e3d80dca67a2f14352cf46ae", "body_sha256": "bd3dd25723a5fd293798db3257f7a02d4cf0044dabe881d30e5e0faf1d96541e", "word_limit": 61}, {"stimulus_id": "P027", "submission_id": "otucse", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nSorry for formatting, on my phone. \n\nBack story - I (f26) found out when I was 21 that I have sever allergies; basically my body would just go into shock and the episodes would last for weeks, even months. I’ve done every test under the sun and we don’t know what is causing it. My doctors decided to put me on a medication that suppressed the reactions and I’ve been able to live a normal life. One of the major draw backs is that I can’t fall pregnant while on this medication. Last year we decided to see if I could come off the meds after being on the for several years. It worked for a few months but then my body crashed hard and fast and resulted in several ED trips in two weeks and almost dying several times. I’m now back on my meds.\n\nNow my partner and I have been living together for awhile, and we’ve now got family and friends asking when are planning on starting a family. It’s always an awkward conversation and we usually just say “oh we’re still young” or “oh once we’re more financially stable”. \n\nThings came to ahead at a BBQ with all of our friends and family. The question came up, and to be honest I was over it. So I just said “well I can’t have children, so that’s that.” It ended the conversation very quickly, but my BIL’s gf heard this. She then came up to me saying how sorry she about this and she can relate as herself is also infertile. I quickly explain that it was due to my medication and that I was sorry for her situation. She was really quiet for the rest of the afternoon. \n\nThe next day I get a call from BIL yelling at me for lying about not being able to have kids and rubbing it in gf’s face. I honestly didn’t know about her story and did feel pretty bad. I asked a couple of friends who know about my issues, and while they agree that I am technically right about me not being able to have kids, I am a bit of an asshole for making her feel shit because if I came off my meds I can technically still have a child. Partner, MIL and FIL don’t really want to get involved so they are staying pretty quiet, but BIL is demanding an apology and gf is refusing to come to any family events until I do. \n\nI don’t think I’ve don’t any wrong as I didn’t know but should I just apologise to keep the peace?\n\nEDIT: I wasn’t very clear with what happened when I came off my meds. I got to seven/eight months without my meds and I was able to live a somewhat normal life. My health declined very quickly, one day it was just one small reaction on my skin and within a week I was hospitalised as I was in shock and my body was starting to shut down. I also need to be off my meds for at least six months before I can even try to get pregnant.", "prompt_sha256": "c78cc90e75a599398a34f3e7af443b97c271f9765765313345af280fb41d80f9", "body_sha256": "d0f7e4587fdedde6f0b600f57825277a43c50c2ff68cca9113c2ff7bf9ecde6a", "word_limit": 61}, {"stimulus_id": "P028", "submission_id": "zvit1x", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nHello so my cousin (19F) and I (20F) planned on coming  to my grandma’s house together, since we both live in different cities and haven’t seen each other in a while. I arrived on a Thursday and she came on a Wednesday everything was normal and fine. We decided to go to a bar (it’s legal to drink where I’m at) and had a few drinks with her friend and her friend’s cousin. We were listening to music laughing and just generally having a nice time.  After a while we all got pretty drunk and she started talking to us about a guy that she’s been dealing with and how much he’s hurt her feelings because of his general lack of interest in a relationship, this then escalated to her telling us that she was pregnant and had taken a test the day prior. We all freaked out since she’s so young but we were willing to be there for her in every way possible, even though my cousin and I aren’t particularly the closest.\n\nThe next day after we sobered up a bit we went to my grandmas house finally, and all throughout the time we were there all she did was break down in tears because she claimed to be so frustrated and upset, she essentially spent the whole christmas upset and I consoled her throughout it all, she would complain about how pregnancy is bloating her and making her emotional and crying about having to have an abortion to not disappoint her parents. She also asked me to wear her uncomfortable shoes for her, since shes pregnant and everything hurts and I obliged. She also ended up telling the guy she was pregnant and he was worried and frantic because she was ignoring him and he couldn’t get ahold on her. On Christmas day she kept breaking down tears talking about how hard it’s been for her and I of course empathized and we also built a little bit of a bond.\n\nSo on Sunday night I ask her “how far along do you think you are?” And she answers with “I don’t know” and I tell her she should try her hardest to find out as soon as possible. She then starts freaking out and getting anxious since the guy was frantically texting her and I tell her she should just answer and work it out with the father. She then turns to me and says “there’s nothing to work out, because this is a prank. I lied and took it too far”. I at first didn’t believe her since she lied so well and I confronted her and asked her how could she ever do something like that? She answered with “Don’t be so dramatic it was just a prank.” But I honestly after this can’t bring myself to speak to such a manipulative person because her ability to so casually lie, fabricate tears and all that just for attention is scary and I never plan on speaking to her again. She claimed I was being cold and if I wanna stay mad and be cruel that’s fine and she wont chase after me, so AITA?", "prompt_sha256": "21547184bb9ad53e3ed36cd8c90808eaaa8dd613bcd4ab1658362f5df7218ae0", "body_sha256": "804e95b996371c1beeb1bff1579178a6b3cbde217b3e869663fb099a80611796", "word_limit": 61}, {"stimulus_id": "P029", "submission_id": "var92b", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nI (30m) have had a horrible last year. \nEnd of last year my father, who lived with me, passed away. And soon after I found out my mother was sick. \n\nTo help my mom(66F) and get away from everything that was going on, I packed up my wife and kids and moved them back home across the country. \n\nMy older brother(48m) was staying with her at the time and was stealing money from her, not taking her to appointments, pawning her stuff, ect. And I found once I moved in that he was also on Meth(this news came out after he stole my sons(9m) bike). So I chased him off to keep him away from our mother and definitely my kids. After a few weeks my mom broke down and moved him back in with promises he would stop doing drugs and get a job. \n\nI began taking my mom to appointments as soon as I got here, and turns out she has stage 4 lung cancer. \n\nShe quit working and I began paying most of the bills, and my wife and I began doing everything for her from going to store, helping her shower, making her food, and giving her meds. Since she can no longer even stand out of bed for longer than a few minutes without getting out of breath. \n\nEvery month she ask me to pay more and more of the bills because she can’t afford them, but she is paying for my brothers car payment, insurance, and giving him money. \n\nLast week I had my last straw with my brother, I found a baggy in drive way with drug residue and he asked if I would give him money or buy a stolen tablet from him so that he could get away from the house, because he had drugs in the car. \n\nI told my mom I can’t have someone like this around my kids and if she was going to let him stay, we would be leaving… she told me “okay I guess you are leaving” \n\nYesterday I got approved for a rental and sign papers this week and get keys. Knowing he does nothing for her I feel almost like I am leaving her to die. And my other siblings, aunts, and uncle are all telling me I am wrong to leave. (All the same people who lived within 20 minutes of her and never took her to appointments or helped her, and asked me to move 2500 miles back home to do it)\n\nBut with everything.. AITA for really leaving and putting my family first?", "prompt_sha256": "ea475cc10edf5cdce8bb5231b78164c00fada820f1fb3001a09998b047348f81", "body_sha256": "3f1fd74ae01ea30094e73b0687f95fe54c523d188d43c636bdbe7630beee5087", "word_limit": 61}, {"stimulus_id": "P030", "submission_id": "1bcwtqo", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nMy sister who recently moved overseas for work with her family recently got very angry when my dad booked a flight to visit them in a few months without telling her until AFTER he had already made the booking. She said it was very rude and disrespectful to do that, especially when she had previously told our family not to book flights to visit her without giving her the heads up first. This was as recently as a couple of months ago when I had also made a booking for my own family to fly over to visit on our holiday without telling her until after we had made our plans and booked our flights.  \nI think she is just being difficult, and she should just live in the moment, and I think it’s a nice surprise to just make our plans and tell her, but she says it’s rude and disrespectful and assumes that she will now need to organise her own plans with work and her own holiday leave around us when we visit.\n\nThere was also an incident in the past where she and her husband booked a flight to visit our family, but we had forgotten about it and booked a trip for my family and our parents and so there ended up being no family in town for her to visit when her flight was already booked.  \nAITA?", "prompt_sha256": "2e5a228b144fbefaae42c6e28d8972074386d03f8c16664aa04628955d9fb6f8", "body_sha256": "ea039d3c50791e98293992599566c1a356a1ffe3732cca7ee468bd88bdfba0ff", "word_limit": 61}, {"stimulus_id": "P031", "submission_id": "u2ime0", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nMy (26,F) sister (24,F, Mandie) recently did something to me that not only hurt me, but also enraged me. \n\nWe were both looking for jobs at the same time. I helped my sister write her resume (she did not help me with mine). I was so happy for her when she moved to the next round for one of her top choices. They asked her to send a sample of a PowerPoint she did, but she did not have one. \n\nI modified a PowerPoint I did in my previous job for her to send to them. When they moved her to the next round, they asked for a portfolio on a PowerPoint. I didn't help as much with this one, however I did embed links for her and provided detailed feedback anytime she asked (most of which she used).\n\nA week after she got a job offer, I was notified that I was moving to the third round (a group call) for my first choice. I asked my sister to send me the the portfolio she made because I wanted to use a similar format for my portfolio (which I planned to send to the group during / after my interview).\n\nAt first, my sister said she would send it to me but seemed in no rush to help. I asked her again later that day, and once again the following morning. The third time I asked her, she freaked out on me and said \"why does everyone in the house rely on me to do everything\". She didn't end up sending me the document. \n\nFlash forward to a few days later. My sister is stating her new job. She's already asked me for help with her WHIMIS training, and I politely declined. Today she was panicking because she needs to fill out TD1 by the end of tomorrow, otherwise she doesn't get paid for another three weeks.\n\n I know where my mom keeps those documents, and how to fill out the form. My sister asked me for help because she knows I've done this for my last job. I was making dinner, so I said \"no, because everyone in the house relies on me to do everything\". \n\nMy sister started crying and said that \"she'd remember this\". She doesn't even realize that I was saying the exact thing she said to me when I asked her for help. \n\nAm I an asshole for literally not giving a shit that she won't be paid for another three weeks. I don't care if she fails her WHIMIS training (I'm sure she won't, but IDC). \n\nAlso, am I an asshole if I don't explain to her why I'm doing this to her? Part of what pisses me off is how self-absorbed she is and, given her history, I don't think she'll think she did anything wrong no matter how hurt I am. \n\n**TL;DR** I went above and beyond to help my sister write her resume, and get a job by letting her pass my work as her own. When I needed help, she didn't help me and even yelled at me.. all I asked her for was to send a file. Now she's starting her job, I am not helping her with basic things (i.e. filling her TD1 so she can get paid this week). She freaked out on me for not helping, not noticing it was the same thing she said t me when she refused to help. I don't even intend on explaining why I won't help her (unless she asks).", "prompt_sha256": "3ecac1c12b71cbbed84a6fe9fe9709103967f3315636a94bae1d432d98b706fa", "body_sha256": "4f97a60d8b098a117224c2214a09840cd4d662bd87dc089ec3931196964a9ce4", "word_limit": 61}, {"stimulus_id": "P032", "submission_id": "my9quq", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nI (32m) have supported my wife (32f) and daughter since our daughter was born. Recently my wife got a job and gets paid pretty well, not as much as me, but pretty well. \n\nI only ask her to pay for childcare, I pay the rest (both cars, insurance, cellphones, internet, rent, utilities, groceries). She constantly tells me that she only has so much money in her account and rarely pays for stuff when we go do things. She also hides her account balance from me, while having full access to my account which is a joint account. \n\nWe constantly bicker about her lack of willingness to pay for stuff because she \"doesn't have money.\" She will not hesitate to use my money for stuff because she says I have all the money. \n\nToday she said she only had a few dollars to get some food on the way home. She asked me if I wanted some food and I said well it sounds like you don't have enough money. Her response was that she will just use my card to pay for the food. I once again get aggravated that she will not ever use her money for us, but doesn't hesitate to use mine. \n\nAITA for being aggravated at my wife for hoarding her money while freely using mine, while I pay for the majority of the bills?", "prompt_sha256": "604577e407f48df48dd00fe96a77d137e0ec56b3584501e4fba0e46e35de22b1", "body_sha256": "8d985fb28612eb2bcabf4e36d66e9f92f277e4684c469e3ff68f8167740b106b", "word_limit": 61}, {"stimulus_id": "P033", "submission_id": "euttsz", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nI am 17f and I had a job as a camp counselor last summer. It was horrible.\n\nThe pay was hourly but we all worked way more hours than we are allowed to report on our time sheets. Minors are only allowed to work 48 hours a week but there is really no time off at camp. The day starts at 7 am and ends at 10 pm. Not to mention if kids wake up in the middle of the night, or pee their beds, then more time. So 15 hour workdays, 7 days a week. 105 hours a week. We're only allowed to report 48 a week, which means only getting paid for 48 a week. \n\nThere is no cell service or access to landlines for us, no internet access, no transportation except cars on or off the camp which is deep in the woods. None of us 16 or 17 year olds had cars. I feel like more people would quit on the spot if they had a way to leave. \n\nSo, onto the drama. Two months into the summer, the camp was having a staffing problem. They'd fired one guy. That guy's three best friends quit on the spot with him. Two international counselors quit soon after. \n\nI was working at the arts and crafts shed, along with Tom who's 17. We're good friends and I kinda have a crush on him.\n\nOne of the girls in our group was the camp owner's daughter, who is really really spoiled, she's used to getting everything she wants if she says \"but Susan's my mom!\"\n\nShe wanted more craft supplies, and I said no, every child only gets three because we need enough for everyone. She started a screaming crying fit going \"But I want them! My mom's Susan, you have to give me them! you have to!\" It was silly but it was my last straw, and I was like \"Actually I don't have to do anything.\" She goes \"Yes you have to, Susan's your boss\"\n\nAnd I go \"Not anymore.\" I went to leave and Tom followed me, he said he was done here too. We ran into another counselor with a radio on the path and said they should radio the office to send someone else to the crafts shed, we were quitting.\n\nWe packed our duffles and walked away, it took us almost four hours to walk the dirt road out of camp and to the nearest small town, where we went into the dollar store and asked to use a phone because we had no cell reception. His parents were only two hours away so they came to get us that night.\n\nThings apparently got crazy behind us. The counselor we'd told about quitting didn't know who we were so nobody knew who had quit for a while. The camp director was furious at us for having left the children alone, but also furious that we, two minors, had walked off with no ride and no communication with parents. I guess we were in a weird place where we were employed and responsible for children while also legally being children they were responsible for...\n\nAITA for quitting and walking out?", "prompt_sha256": "4493aa753e830401c155ddf6cd34c6b8878637339c80c8eccf114e6cacf15e77", "body_sha256": "8109a3dd120d23cd7c6a831dd494c6d7a32041c098dda7fedcf361db8e88751e", "word_limit": 61}, {"stimulus_id": "P034", "submission_id": "fw2htu", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nSo hear me(M37) out here on this issue with a family member. My wife and I have two kids who are 2 and under. This family member has the same thing but one of her kid has some health issues. Their little girl has a G-tube and some breathing problems that seems to be getting better. Every time my wife and I do stuff with our kids and wife posts it on social media, family member would comment with stuff like: \" Imagine doing that with two kids and one with issues\" or \"Try getting out of the house in the morning with the oxygen tank, etc...\" Or if we are together and kid is doing something that her other one can't she'll mention \"Could we not have your kid do that so that mine won't want to do it?\" I think the other day was the last straw because my wife posted a picture of our kids at my parent's house with their Grandma because we both had to work(no WFH option for us) and she made a post about how because her kid has health issues and can't see their grandparents (because of what's happening) so people shouldn't be posting things like that. It feels like she's using her kid's health problems to make backhanded comments or us feel bad about doing things. So Reddit, WIBTA if I call her out on that?\n\n\nEDIT: Some info, I don't actually use Facebook or Instagram that much as I don't like to put pictures of my kids on there. So these comments that I see are mostly when my wife let's me know. We've both mentioned it to each other about how she would take a swipe like that and we know it's towards us. She's also like a sister to my wife so it'll have to be a very friendly worded conversation. Lol.", "prompt_sha256": "fef381d65d4311acc2e115d96ea05ddde2b42861ba16aa527fdf4f2616b737a3", "body_sha256": "478e5c0fc5b17c43509742766465c39483a2e8507b5d363c1e81b62cbba6d6ef", "word_limit": 61}, {"stimulus_id": "P035", "submission_id": "ye8mp6", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nLong time lurker first time poster. I (21m) am engaged to my fiancée, Tina (25f). We’re currently planning our wedding. We are both bisexual. Right after I turned 19, me and Tina started hooking up with this guy, Todd, who is a friend of mine, but we stopped after we realized it wasn’t for us. He understood, and he just got into a serious relationship with Hannah. Well, 3 days ago was our engagement party, and Todd was there with Hannah. \n\nMy sister, 29, made an off color comment about how she’s surprised that Todd  was there, and some people asked what she meant. Before I could stop her, she said, “well, I just didn’t know my brother and his fiancée’s old passion partner was invited to any social gatherings, that’s all.” Along with some other stuff. Then, silence. Things escalated at that point. Multiple of my family members and Tina’s are deeply homophobic, and we weren’t planning on coming out to them. My parents, who didn’t know about my old arrangement with Todd, tried to keep the peace and calm everyone down, but were clearly upset, but I don’t think I needed to tell them or anyone about me and Tina’s past. \n\nTons of family members ended up leaving, and some even threw the food they brought away, and they all said there’s no way they’re coming to the wedding of “such heathens”. I was furious at my sister, and she just said it was insulting to the LGBT community that I’m not loud and proud, I shouldn’t be ashamed of who I am, and I shouldn’t hide it. (She’s gay, BTW). I freaked out further and said that she should know how bad it is to out someone, and that I’d never do that to her, but she basically just said, “Tough shit, besides, do you really want homophobic relatives at your wedding? Consider what I did a favor.” \n\nNot to mention, now Hannah, while not angry at Todd, felt blindsided by the fact that she only knew he was bi, not that he had been with me and Tina. Now his relationship is shaky, my situation has spread like wildfire through my family, with some relatives defending me and Tina, and others disowning and being disgusted by us. I’m seriously considering cutting my sister off and disinviting her from my wedding, which may have to be postponed because of this, because her dad, who was gonna pay for the wedding, is having second thoughts because of “the controversy.” My parents said that while they love me, they don’t support my lifestyle, nor the fact that I’ve done it premaritally. They said that while they understand where I’m coming from, they think it would be a gross overreaction to completely disown my sister, but my life has been flipped upside down. \n\nLiterally, the only person who still 100% supports me is Tina, even Todd is trying to distance myself from me because of my sister. For clarification, she only knows because of one time she borrowed my phone without asking to order pizza, and she saw some texts and a picture that Todd sent. WIBTA for cutting her out and disinviting her for good?\n\nEdit for clarification: she hasn’t come out to anyone but me yet. That’s why I think she’s such a hypocrite in all this. And to those saying I should out her, it deeply hurt me and psychologically fucked me pretty bad when she told everyone on her terms. It seems cliché and predictable, but I wouldn’t wish that on anyone, not even her after what she did to me. If she does make the choice to come out, it should be on her terms, no one else’s. If it hurt me this bad, and I can play things off like I’m straight because I’m a man marrying a woman, I can’t imagine what it would to to my flesh and blood sibling, who can’t just marry a man and choose not to out herself. And plus, revenge never ends well. \n\nIt becomes a vicious cycle of escalated viciousness towards someone else, and I don’t want that for me or her. I have too much at stake right now to risk her or anyone else messing it up. Even though my sister deeply hurt me and did irreparable damage, I still love her, even if I don’t want her to be in my life. I don’t wish ill intent towards her at all. Also, as another Redditor pointed out, my sister probably did this to punish me, because even though I’m part of the LGBTQ, I’m marring a woman. She doesn’t have that luxury, to be able to play her relationship off as straight. So in hurting me, she made it easier to live with her truth, because now that my truth is out in the open, any relationship she has in the future I’ll cause turmoil, but I’ll be dragged down with her.\n\nEdit: she found my post. I’m waiting for the fireworks… I’ll keep y’all updated\n\nEdit: my sister is PISSED that I’m even **considering** cutting her off, because she “supposedly”, “did me a favor”, and she is thoroughly upset that everyone is “seeing her as the bad guy.” My parents said they’re not coming to the wedding either since I turned a bunch of strangers on the internet against their, “precious baby girl”, but they’re also upset that she’s also gay, and wondering where they went wrong to have two gay kids. They blame me for, “spreading my homosexuality to her.” My sister sent it to some other more progressive family members to try and get them on her side, but they aren’t having it, and from the looks of it, she outed herself to them. Things aren’t pretty, but I’ll keep you posted further. Thanks guys.", "prompt_sha256": "5697496028f53e86b1d872e158515b58e227f5a99a01bb77dfe8bfd8a003b710", "body_sha256": "26af2233b82f6ff9b5313143970652e31d8fdbaf492795d9d40b3c7cdd8ec965", "word_limit": 61}, {"stimulus_id": "P036", "submission_id": "g2hyoe", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nI’m in a group chat with 8 other people. We all go to the same grad school. John said: “Hi everyone. I received a diagnosis.” He never even announced he was sick or seeing a doctor, at least to me, so I was afraid that he had cancer or something similarly serious.  Another friend responded: “Oh no, is everything okay?”  After a two-hour long pause, John said, “I will be okay...now. I have been diagnosed with ADHD.”\n\nAs a person with ADHD, this struck me as obviously being much less serious than a terminal diagnosis, and not worth the drama. I said, “Man, I thought you were dying or something, that was really dramatic!” He didn’t respond to me and the conversation moved on. A mutual friend of me and John messaged me and told me that John was very offended by what I said. John thinks that I was minimizing his very serious diagnosis, a diagnosis he sees as a revelation and the reason he’s always struggled to succeed in work/school.  Since this was told to me in a covert way, I didn’t see a space to apologize or explain myself.  I don’t even know what I would say...That I still think that saying “I received a diagnosis” in a group chat and announcing an ADHD diagnosis is overdramatic?\n\nAm I being an asshole here?", "prompt_sha256": "fb3e52b23461a36259ac4c0751c971583c84bf558f7ad7350407c29fea2486e0", "body_sha256": "298faf536d09ffa4a1a5c44493f74b06401349ff204214a31adbe5aeab0a64d8", "word_limit": 61}, {"stimulus_id": "P037", "submission_id": "12zgnif", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nDisclaimer: This is a throwaway because I have a more active account that my friend knows and they are also semi active on Reddit. Fake names will be used as well.\n\nSome background: I (27F) have a best friend of 8 years (26m) David. I met David through a mutual friend of ours. We got along well and became best friends. I lived in a different city than David and when he was not happy being at home in his small town I invited him to live in my city a few years ago. He is gay and never felt accepted so he was really happy being here where there is a much bigger LGBTQ+ community and it’s generally more accepted. He’s made a LGBTQ+ friend group here as well.\n\nThe issue: David texted me asking to borrow $5 until the next day so he could get food. But because his bank is overdrawn I couldn’t send it that way and he wanted me to use Apple Pay. David lost his job last year due to poor choices he made and was unemployed for about 6 months. During that time his roommate (which is my old coworker Amy) paid for 100% of their bills. When he started working again he was trying to pay her back, me, and his friend who I’ll just call Bob. David isn’t the most responsible person and usually makes poor financial choices which has left him overdrafting his account at least 1-2 times a month ever since he lost his job a year ago (he overdrafted a few times before losing his job but not nearly as often). I’ve repeatedly told David to stop going out so much and spending money and that even though I know it’ll be boring he needs to stay home and save. And I know it really sucks that means no more drag shows, parties, traveling, bar hopping and whatever else he does. David never listens to me though and continues to go out with his new friends he made. What upsets me is that every time he needs help he always asks me for financial help. If he can pay me back right away he does if not it gets added to his tab he owes me. I have repeatedly told him to stop asking me for money because I’m not as financially wealthy as he likes to think. I live off the bare minimum needed to survive and any extra money I have goes towards my student loans and my savings account. But he always makes excuses and says where he grew up is a small town and they didn’t have much to do and he was never accepted there. And now that he lives in a bigger city he wants to live life and have fun. I’m not denying him that right but you can still have fun and make smart financial choices. So when he texted me asking to borrow money I just ignored him. But now I’m starting to feel guilty and I’m thinking I should’ve just lent him the money because I know he’s going to be very upset with me since that’s what always happens. AITA?\n\nEdit: I’ve spoken to other people in my life and they’re also saying I’m TA and I should’ve just lent him the money and not expect to get paid back because it’s for food which is a necessity.", "prompt_sha256": "8273e224776c3c724fc09dc465b56bed0608fc6b05d48d27a2cb94b2a32518b2", "body_sha256": "0e4c260511b72d6048bd2df708eb6923df7a7c2f9bdde2d52cf8d29064cacdb8", "word_limit": 61}, {"stimulus_id": "P038", "submission_id": "inu97u", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nMy late wife passed away three years ago, I been married with my current wife for 6 months now.\nMy son (15) disrespects my wife and would always hurt her with his words.\n\nI tried to get him to get used to his new life but he always says he can't wait to leave.\n\nMy son has always wanted to go to college, he's aiming to go study at his favorite which is out of the state.\nHe wants to be a doctor it's his dream, his mom passed away from cancer and he said he wanted to be a doctor, do researches to help people with this type of diesease, I thought that this shows the good side of him and how emapathatic he can be, I just don t get why he doesn't get along with his stepmom, she's always nice to him, her feelings were hurt when he yelled at her for cleaning up his room this morning.\n\nI told him that if he doesn't start treating my wife with respect then I won't save up any money for his college and will just send him to a tuition-free community college.\n\nHe got mad at me, told me I was trying to buy him with my money, and that I was being a horrible daf, he brought up his friends and how lucky they were to have good dads, I cut the conversation and told him to go to his room, he started crying and said that I care about what my wife wants more than him.\n\nI was just trying to give him consequences for his behavior but it just got worse, he doesn't want to talk to me anymore.", "prompt_sha256": "8853053f8f42dd97f2cbbe911e25692b377e664ed3242ed088acadfbe2c87063", "body_sha256": "2f5ebbaf990f1bb7b17ae6473effad876c3f615945183dbe28c6482044975668", "word_limit": 61}, {"stimulus_id": "P039", "submission_id": "1czsk5w", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nI’m 16M and I have been homeschooled by my father for pretty much my entire life, my mom died when I was 5 and then my dad took me out of school and started to homeschool me. \n\nWhen I was younger I enjoyed homeschool a lot and I remember loving that I got to spend so much time with my dad. But I never really had any friends, I did go to Scouts but that was just for 1 hour a week and dad never lets anyone come over to our house or lets me go out with friends. So most of my friends are from Reddit and discord. \n\nI’ve approached my dad about me joining back with normal school but he doesn’t want me to. But I really want to, so I applied (Idk if that’s the right word) for the college in our town in secret and I was just going to go with the “ask for forgiveness, not permission” route with my dad and hope things worked out. \n\nBecause I didn’t want my dad to find out my friend I made on discord told me to put down my address as his address (we live in the same town) so if they send any post my dad won’t see that I’ve applied. They sent out all these forms that need to be signed by my dad, but obviously he won’t sign them. My friend said that he will sign them pretending to be my dad for me. \n\nThough I want to go, I’m starting to feel nervous about the whole thing. I worried about if my dad goes mad at me for signing up. My dad will definitely be mad at me for doing it and he will be super mad if he knows I’ve got someone to fake sign the forms for him. \n\nMy friend is encouraging me to do it anyway, but now I’m getting second thoughts and will just probably not do it because I’m worried about how my dad is going to react. I think probably this was all a stupid idea anyway because I don’t even know how I would get to college everyday. \n\nBut on the other hand I really want to be normal and I don’t feel normal being homeschooled and stuck here all the time and my friend says if I do go we can finally meet up in person. He doesn’t go there but he said he can meet me up after the day or something.  So that makes me want to go it. \n\nWIBTA?", "prompt_sha256": "20f6ef642e24d53eca3c7a53608976fef0ecd7ff565733c40b380d63769fb1b4", "body_sha256": "54e66ab6f9ae18c9f02f30c4c6a77f7f03bcb96967dfd5b364847f53de07c28a", "word_limit": 61}, {"stimulus_id": "P040", "submission_id": "1k4a6ob", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nUgh. This is so stupid but I'm still mad about it.\n\nYesterday my girlfriend (32F) and I (35F) threw a little combination Easter-4/20 get-together for some friends in a large public park that included, as one element, an Easter egg hunt. This is a big local park where people often do small private egg hunts for their families and friends, so the idea isn't totally out there. We bought around 100 plastic eggs, stuffed each one with 2-3 pieces of candy, and hid them within a smallish area of the park about 20 minutes before everyone else was due to arrive. We figured because the weather was nice, we'd probably lose a few eggs due to kids walking by and stumbling on easy-to-find ones, but we bought enough that we could absorb some marginal losses. Some were pretty visible, others psychotically well-hidden, most were pretty much in the middle - you'd have to really be looking to spot them walking by.\n\nWhile we were waiting for all of our friends to arrive, we noticed three kids running around the area where we'd hidden them, and they all had their arms FULL of eggs. Like 15-20 apiece easily. Their mom was sort of trailing behind, not paying attention, and on the phone. It got to a point where we finally got her attention and she literally went, \"Is it okay if they take these?\" My GF and I were both dumbfounded. Because, again, we figured we'd lose a few eggs to kids who grabbed one or two. But this was EGREGIOUS. They had easily 50 between them. There were 15 people coming. Yes, they were all adults, but adults also like to have silly fun too!\n\nSo we basically told her, uh, no? Please put them back? Her response was some version of \"They're just kids! It's a kids' holiday!\" I asked her if she usually lets her kids take candy from strangers off the ground in public parks, and said something along the lines of, \"Weird parenting choice, but okay,\" and she got huffy and told the kids they were leaving and to put them back. The kids threw some of the eggs on the ground but still left with probably 40 eggs in total. Again, that's... 80-120 pieces of candy that we bought. For our friends. And ourselves. Not for random children who didn't even bother to ask before taking it. (If they'd asked, we probably would've said sure, within reason! 2-3 apiece! NOT LITERALLY HALF OF THEM.)\n\nAlso, as they were leaving my girlfriend called after them, \"Good luck finding the ones filled with fentanyl,\" which was very funny, but I don't think they heard.\n\nAnyway, now I feel like an AH for calling her a bad parent in front of her kids and for ruining their fun, but I also have a real tendency to feel insanely guilty any time I stand up for myself (blame my own mom's stellar parenting for that!), so I just wanted a temperature check. This was objectively insane behavior, right? Or am I the asshole?", "prompt_sha256": "ea2b1b8b01cdd02de9ede94ccbdda04986ce1b8b9b8f0551a1c74ac6d744f328", "body_sha256": "e36ec1e6b56b7a60e098455fde6e7205edd79bd0fe0d897ba753486798a42779", "word_limit": 61}, {"stimulus_id": "P041", "submission_id": "k7uuwb", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nOkay so, me and my fiancée hosted Thanksgiving this year. We were safe, the only people we had over were my older brother and his family and my older sister and her kids. We all quarantined for 14 days before the day they drive over to my city. My bother and his wife have a 4 year old girl and an 8 year old boy. My sister has a 7 year old boy and a 2 year old girl.\n\nI don’t know this when it happened but my brother and sister made plans to let their kids bring their bikes so they could play when we weren’t all together as a family. One of the days they were here, my brother and his wife decided to drive around to explore and wanted me and our sister to watch the kids. I love my nieces and nephews so of course I took care of them. \n\nThe boys got kinda restless and wanted to go outside to play, my sister told me about their bikes and I went to unload them and saw that my bother’s son’s bike had training wheels. I asked him why and he said he couldn’t ride the bike normally. I wasn’t going to do anything about it but I eventually could tell he was jealous that his cousin didn’t need training wheels. So I taught him how to ride the bike without training wheels. It took a while but he got the hang of it and was a pro by the evening.\n\nThe rest of the visit went great and they left. I’m guessing this week my brothers kids are out of school for the holidays so he’s playing more outside. I got a call from my brother and he was livid. He asked if I taught my nephew how to ride without training wheels. I told him yeah, I showed him how to ride the bike. My brother lost his fucking mind. He told me that I should’ve never done that and called me a bunch of horrible names. \n\nI asked why he knew his son still needed training wheels at 8, he said that he just got him the bike and was gonna teach him over the Christmas break. I told him that he should’ve told me that, he said that he didn’t think he’d need to tell me to not teach his only son how to ride a bike. We argued back and forth and he hung up on me.\n\nI kinda feel like shit, but I didn’t know I should’ve taught him.\n\nAITA?", "prompt_sha256": "b19684557da4b2273976c7f641036c6b244ffb18ea37e2d820db1f56e20a0803", "body_sha256": "ff544f2df46c41f620f9c246acf7392a46e687997015b1114f1cbd0bd111fcfe", "word_limit": 61}, {"stimulus_id": "P042", "submission_id": "1hc29d8", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nLoooong time lurker, so here to figure out if I'm wrong here.\n\nMy (36F) boyfriend (32M) of two years is a bit on the irresponsible and immature side. We had VERY different upbringings (he is upper middle class and lived at home until moving in with me last year, while I had a very rough childhood and moved out 2 weeks after turning 18) so he wasn't really forced to grow up as fast as I was. This comes out in different ways, but the most recent way is his car. \n\nHis car broke down 5 months ago. It needs a fairly simple part, but he has just let it sit for the past 5 months. We use my car for everything, which, yes irks me and I have told him I don't like him taking my car all day or that we use it all the time, but he usually reverts to he doesn't have the money to fix his. \n\nWe do have a large income gap, he makes about 30k to my 150k so I also pay for everything. His only expenses are his cell phone and car insurance. I pay rent, utilities, food, internet, all the household expenses. \n\nHis job is also intermittent (he is crew in the entertainment industry). He has a job coming up that will require him to be out of town for 3 days. I've told him he is not taking my car and leaving me stranded for 3 days. Do I have anywhere super important to go? Not really, but its my car. I paid for it. I would like to use it when I want. He get very sad looking and apologized that he doesn't make very much money which made me feel horrible. \n\nBut the thing is, the part needed to fix his car is $200 and he can put it in himself. He recently bought $170 headphones, two video games that were $130 and more random stuff that he just didn't need. $50 here, $100 there. He also keeps telling me about his investment accounts that he opened. So he HAD the money, he just chose to spend it on fun things and opening a Charles Schwab account when he doesn't have Charles Schwab money, rather than his car. When I brought that up he said he \"didn't have a reason until now to get his car fixed\" and now he \"doesn't have the money.\" I honestly think he was waiting around for me to buy the part for him. And now he says I am jeopardizing his job by not letting him use my car because now he doesn't have time to get it fixed and he doesn't have the money. He says that partners help each other and we are supposed to be a partnership. But to me, a partner doesn't constantly use their girlfriend as a safety net because they're irresponsible. AITA here?", "prompt_sha256": "b42da62e7fdb26e426c8ecc9a63a485482a61fa47e2f67e95e95b1f285ee099c", "body_sha256": "9030d8ff3120f6978a83851b76414277315deead421a6f47cad404df13e90ac8", "word_limit": 61}, {"stimulus_id": "P043", "submission_id": "f6n1b1", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nTLDR:My friend has been struggling with drugs and alcoholism, so I'm trying to get her newborn son into a foster home.\n\nFor some background, I am a 32 year old female, my friend is 33 years old. I have been friends with her for 16 years and I realize she has been struggling lately with problems to her health, including drugs and alcohol.\n\nIt was 1 year ago that my friend had her baby, and as much as I am happy for her I cannot allow the child to be growing up in an environment where he is at constant risk to his health and being neglected by his mother.\n\nThe father has been gone since before he was born, and with a mother on dangerous substances, I feel like I should be fighting to get the baby out of this environment. \n\nSo Reddit, am I the asshole for trying to get my friends baby out of there?", "prompt_sha256": "f7648849bb18ea47543adfc3504cf91eacf59506652450a901b4b35009b8a232", "body_sha256": "9b44db6137abaac4944b9cd82bd76f62f7e8e3dc5526339601b1ef14c59c465a", "word_limit": 61}, {"stimulus_id": "P044", "submission_id": "emch4u", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nI'm in high school, my dad is in his 50s and my stepmom is in her 30s. (Yeah it's as weird as it sounds) They have an infant son who cries all the time. Kinda sucks because I'm really stressed about school, this year is really important for my college admissions.\n\nI'm really into camping and the outdoors. Making forest shelters by hand with stuff I find in the woods, camping, hiking, etc. (Like the primitive technology YouTube channel, but not as good lol). I've been camping and backpacking ever since I was little, with my mom.\n\nMy dad's house is on a lot of land and I've made a bunch of forest shelters out there, over the years, it's a hobby of mine. I know it's weird, but it's fun and relaxing. In the past, my dad had never had issues with me camping out there to test them out, or whatever.\n\nAnyway, I hadn't been getting much sleep at all with my halfbrother and stepmom here. He cries all day and night, and she's an early waker who makes a racket first thing in the morning.\n\nSo thr last few months I've been camping more and more. It's cold but I have a really good subzero sleeping bag, i can make a fire, I'm comfortable. And I sleep like a log; I've always slept well in the woods and it's a whole lot better than trying to sleep in the noisy house.\n\nIt's causing such a fuss for no reason, my dad is saying he doesn't like the idea of me sleeping out there alone in the winter, and I said to him that he never had a problem with it before, he's been letting me do it for years alone and it's always been OK, it's not fair for him to take it back because he's probably mad I'm the only one getting any sleep.\n\nMy stepmom says it's disrespectful, my dad puts a roof over our heads and I go to sleep in my little forts every night? That it's like what a child would do, not a young lady. \n\nThey haven't stopped me yet but I'm worried they will. I also don't see at all how I've done anything disrespectful but maybe there's just something I'm not getting?\n\nAITA for sleeping outside?", "prompt_sha256": "d3375693365e4ffc5dac54be1401e06dd93d087803bb2db9dc1752a9ced6a6f0", "body_sha256": "607acec4fd12dd6f635de6d96a57b1b9a7cdc8c5b5285f7a59b7a7e9fdb9d222", "word_limit": 61}, {"stimulus_id": "P045", "submission_id": "1d9o2ie", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nThrowaway for privacy. I’m 21F. \n\nAs a post-graduation trip, me and my friends are going on a trip to France next summer. This is my first time going to Europe so I’m really excited, and we’re currently in the planning stage. This issue concerns one of my friends, Katie (also 21F). \n\nKatie has never been out of the country, and somehow she’s gotten it in her head that the worst thing someone can be in another country is a tourist. I think she’s read too many articles and watched too many tiktoks about how Europeans hate American tourists. Anyways, she’s now trying to change our trip to be as un-touristy as possible. For example, she’s sent the rest of the group pictures of French street fashion and is insisting that we can only pack outfits that look like it. When one person said she didn’t have clothes that looked like that, Katie just said “guess you’ll need to go shopping.” She also says that Europeans do not wear sneakers and will immediately label us as tourists if we’re seen wearing them, so we can’t bring them (even though we’ll be walking a lot). \n\nAdditionally, when I tried to suggest places for us to visit (Eiffel Tower, Louvre, Versailles, etc), Katie immediately shot them down and said that those are too “touristy” and we should try and find other places to go. When I asked her what kinds of places, she pulled up some French residential neighborhoods and local shops and said we would be better off spending our time there since it’s more “authentic.” To be clear, she’s not concerned about avoiding pickpockets since we’ve already purchased pickpocket-proof pouches. It’s JUST about “looking like tourists.” \n\nIn my view, there’s nothing wrong with being a tourist and doing touristy things as long as we’re respectful of the locals and French culture. Besides, if I’m only getting a limited time in France, I don’t want to be spending it all just walking around random people’s houses and looking at them like they’re zoo animals. I told this to Katie and she got upset and said I was the reason why Europeans hate tourists so much. I told her we ARE tourists, why try to hide it? I’m pretty sure French people would be MORE annoyed if we tried to act like locals instead of just being respectful visitors. \n\nKatie got even more upset and said that if I want to be disrespectful of French culture so bad, I can go to France on my own time. She then left our planning session. \n\nThe rest of our group is kind of split on this issue. Most of them agree with me and think it’s a waste of time to walk around residential neighborhoods instead of seeing the Eiffel Tower and the Louvre, but they also are very afraid of being perceived as annoying Americans. So I’d like to get some more perspectives on if I’m TA here. ", "prompt_sha256": "52dea5de8fd280ebd79a62180d994bc8d8445f187a6b25c831cb5fffafc9511d", "body_sha256": "76915093750187cc77f94b0ee46febaceb7c3bc0175592d959f5a84ce0eb7a96", "word_limit": 61}, {"stimulus_id": "P046", "submission_id": "16a1sd1", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nHey everybody. This sounds kind of stupid to me but maybe my perspective is wrong.\r  \n\r  \nMy friend/roommate (M30's) who we can call Kevin has an 11-year old daughter who we can call Rachel. For context purposes, she has no physical disabilities or bladder control issues. She doesn't live with us full time but she does come every other weekend and on some weekends for visitation. Every time she does, she's always expecting people to do a lot of stuff for her that she could do herself such as 'my dad will carry my stuff/get my drinks/plate my food/give me some of his drink/food after I finished mine because he loves me'. This came to the point where Kevin actually (finally) told her last night that she can stop coloring for long enough to get her own water. We live in a 2 bedroom apartment with 1 bathroom.\r  \n\r  \nWhen I (F20's) went in this morning to brush my teeth, Rachel came over and said she needed to use the bathroom; I told her to wait and that she can't try to kick me out every time she wants to pee (this was at least the fourth time she's done so this weekend). Kevin tried to tell me that I should leave so that she can use the bathroom because using the toilet takes priority over everything else. To be clear, she came in while I was already in the process and not asking once she saw me. She waited for a maximum of two and a half minutes.\r  \n\r  \nOnce I was out, Kevin and I had a brief discussion in which he expressed that he felt it was inappropriate for me to make either him or Rachel wait when I was not physically using the toilet. My stance is that if someone is doing a short task, they are there first, and it is not an emergency, they should wait their turn. This seemed to be the common rule of shared bathrooms to me, but maybe I was wrong.\r  \n\r  \nAITA?", "prompt_sha256": "a175ee2bf9e4dd4d8a8b65b0a24e8ea5c049ca8de4fc8b3db85848327f75642a", "body_sha256": "2aed00c48ce93f37a2a2acb7382f71e8d225f624f51990657f37935c0476e4db", "word_limit": 61}, {"stimulus_id": "P047", "submission_id": "1884xbf", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nWIBTA if I don't spend Xmas with my family?\n\nMy parents are looking after a family friends house and their dogs in another city over the xmas period. The expectation was that once we figured out work holidays etc that we would fly down and spend Xmas with them. I kind of just assumed that was the case, we loosely talked about it but it was always far away so no real plans were made. \n\nI called my mom the other day and said I was looking at flights, and would this date suit them etc for me and my girlfriend to come down. My mom acted all surprised, she said \"oh you didn't tell me she was going to come, I need to think about this\".\n\nI (male) have been with my gf for about 9 months. She has met my family before, even come on a weekend holiday with us. There was no drama at all, it went really well.\n\nLater my mom emailed me and said \"I'm so sorry, it's been a really tough year, your dad was in and out of hospital, I just want a relaxed Xmas with just the family and not have to worry about anyone else. I'm sorry for the position this puts you in as you have already told your gf She can come\"\n\nI don't know what to do. I feel my mom is being incredibly selfish. I have never been in a position where my partners parents have said they don't want me there, so I think this is incredibly rude of my mom. What does she expect, in the future she can just dictate things and not invite my girlfriend to family events? What if we get married? Is she going to be \"that\" mother in law that excludes my partner if she has the opportunity?\n\nI just feel like I can't be bothered flying down to be with my family and just making up some excuse about work and not going", "prompt_sha256": "9694169dc2c08e41ee738b788e311adb7c9509c5c140a1bb12603142a7d29b3a", "body_sha256": "ce669e74abee76f11236ff0fc0322be751881cdb8a28e8bb952e4a079f3542dd", "word_limit": 61}, {"stimulus_id": "P048", "submission_id": "1k6749o", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nMy husband (33 male) and me (29 female) got married almost a year ago. We never went away on a honeymoon as money was tight. For our 1 year anniversary my husband booked us a 4 day trip 5 hours away from home. Here is the backstory. I am a full time caregiver for his grandma, she fell a couple months ago spraining her ankle. Since getting home from the hospital she has been working really hard to get strong again. To also help me she gets PSWs 3 times a day. Her morning PSW bathes and gives her morning pills, afternoon PSW gives her a change and feeds her lunch. The night PSW gives her one last change and her nighttime pills. I do her workouts and change her when needed. (There can be 5-6 hours difference for the PSW sometimes) I also make sure that lunch and dinner are ready for when the PSWs get there. Grandma can walk herself to the living room (with someone behind her with her wheelchair in case she needs to sit down) and can use the washroom. My MIL also lives with us. She is on an oxygen tank, but still smokes cigarettes. She’s told me multiple times “it grosses her out if she has to change her” I told her it was the same for me, but she says “yeah, but I know you can do it” Anyway, she told us she was fine with us going away as she knows we didn’t go away after our wedding and has the PSWs coming. She also said she was getting a friend to help if needed. Since then she has changed her mind and asked us if we could shorten our trip. We wouldn’t be getting our money back from our booking, so I told her she would need to pay us back half of what we spent (it was 800$) so she would be paying us 400$ When I told her this she got very upset with me, rolling her eyes. Saying “I don’t have that kind of money. It would take me a while to pay it” I told her that was fine. She again rolled eyes and stopped talking to me. So, am I the asshole? ", "prompt_sha256": "3967b968fecdafa11ca29b5a90a1e642a5186e62acc088e33b68cc0ffdae2f9d", "body_sha256": "367524ef6264eeaab5fa6d437813509ce4d5095f920074c28a1554e2c88dd53d", "word_limit": 61}, {"stimulus_id": "P049", "submission_id": "17uj65r", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nYesterday, I took my mom to the grocery store and my car had 3 fuel bar, and I was it will be fine for me to drive there and back and still have plenty of gas. \n\nYesterday my girlfriend asked me if I put gas on the car and I told her no. She was upset about it, and said I should have filled it up. I told her I didn’t go to the gas station.\n\nToday, she called upset because I didn’t put gas on the car yesterday, and I don’t want to do anything for her.\n\nI bought this car 5 years ago, and she is the one using it. I don’t need it for my job. I pay for the car note, insurance, and any repairs that needs to be done. \n\nAm I an asshole for not put gas on the car?", "prompt_sha256": "8950a4fec325ae2b962fcab63cd7f0570507bab2483cc4075f2a6ea8d0d6ce01", "body_sha256": "0fd5c12b2d5d2b8860642f0d237c9151fd9b9fe9b34d550b72ceb2c551cbb739", "word_limit": 61}, {"stimulus_id": "P050", "submission_id": "1gbj8i8", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nI (F24) am getting married to my fiancé (M26) next month and I have not invited any members of my family.\n\nMy roommate (F23) is very much a family person and invites her parents and two brothers round nearly every month. I have nothing against this as I enjoy spending time with them all, but in the 3.5 years we’ve known each other my roommate has consistently asked me if I’ll be inviting my parents around anytime soon. \n\nI cut off all contact with my family at 18 after moving out when I was more or less financially stable due to religious abuse. I won’t go into it, but I was asked to leave on multiple occasions as a minor to ‘clear my body and mind of sins’, and regular physics punishments were put in place when prayers where not long enough and bible verses were not memorised. I do not speak to any of them including my extended family, and I am perfectly content with this arrangement. \n\n I have explained this to my roommate but she doesn’t seem to understand that I genuinely don’t want to speak to them anymore. Our arguement about this haven’t been too disputed until about a month ago when we started discussing wedding invitations; I mentioned that I would only be inviting some good friends and a few of my co-workers, but she was clearly not happy about this. There were many conversations about how I probably misinterpreted my family’s abuse as an attempt at education and sharing culture. \n\nTo wrap it up, I’m getting married soon and my roommate is attempting to postpone it until I sort things out with my parents. My fiancé is on my side completely and has said he’ll support me no matter what. However, some part of me kind of agrees with my roommate’s words; if I was a parent, I’d be incredibly upset to hear that my child got married and didn’t invite me to the wedding. What am I supposed to do? \n\nApologies for any bad formatting, I’m on mobile. ", "prompt_sha256": "420a65da0fdb44b156e7e0693c372868ac2c6790f443b34cb5b20e0a6728ebf6", "body_sha256": "150a50cbd8ec58d12a06f7f0c6c2331fce8bbc62203aa7e1c225d65cb25a4880", "word_limit": 61}, {"stimulus_id": "P051", "submission_id": "1anhrtb", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nMy roommate and I got really into this one singer. Since she moved in really quickly and has always been on time with rent, I decided to surprise her with tickets to the singer's show. They were pretty good seats for only being $300 each. We were having a good time, as much as some of the people there were kind of being obnoxious. Out of nowhere, during a really quiet part, my roommate yelled \"Mother is mothering\" and literally everybody around us started yelling at her to shut up, shut the F up, etc. I straight up told my roommate to never do that again and that she embarrassed me a ton. I apologized to everybody around me and explained I had no idea she would do something like that.\n\nWhen we got home, I told her to pay me back for the ticket because she ruined the show for me. She told me she was not \"obligated\" to, and that this is just how concerts are these days. I told her that because of her, a bunch of strangers cussed at me. She started yelling, saying that people cussed at her, too, and that I was making this all about me. I told her this literally would not have happened if she had concert etiquette like a normal person, and she stormed off and sent me the money, whining about how she had to ask her dad. And I guess she told all of our friends a completely different story, because I got a bunch of texts saying I was a bad friend and that I was using her for money or whatever.\n\nEventually, somebody uploaded that exact moment, my roommate found it, and she basically shut herself in her room since then because of her \"mental health.\" AITA, not for telling her off for the \"Mother\" crap, but because I made her pay me back for her ticket?", "prompt_sha256": "2bdd335af3f8db85b931e6d2b43eda91c62207d88a2e83e5bf05230fbe26818d", "body_sha256": "705546e19a7e14ad17e69fa55561e52b3a2db13434b7ebd70437a5533b85bbcd", "word_limit": 61}, {"stimulus_id": "P052", "submission_id": "x5z3rr", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nI (18f) lost my mom when I was 4yrs old. She had issues with depression before she was pregnant with me &amp; it got worse when I was born. She was a teen mom too with not a lot of support, so I think that just piled up and she couldn’t handle it anymore. She and my dad weren’t together when she died, but ik he loved her a lot, even if they were really young. Her parents still feel really guilty about it all, so they pretty much just let my dad raise me on his own without any input/visitation from them. So I don’t have contact with my mom's side of the family except for her older sister, my aunt (37f).\n\nMy dad (34m) met his wife Mel (33f) when I was 10. She’s really sweet, and even before she and my dad were together, she’d take me out sometimes just the two of us to go get our nails done or go shopping. My dad did a good job on his own, don't get me wrong, but it was nice to have a woman around to do those stereotypical girl things with. When they started dating, Mel still made sure to include me, and when they got married and later had my baby brother (3m) that never changed. I love her a lot, and I feel really fortunate to have her in mine and my dad’s life. She makes him really happy.\n\nSo we have an assignment in my media class where the girls make a video with their moms. We basically interview our mom and ask her what she wished for her future daughter like dreams and stuff and then have a conversation comparing that with how we turned out. I obviously can’t do that with my mom, so I asked my teacher if I could have my stepmom do it instead, and he said that was fine.\n\nI was catching up with my aunt at a coffee place like we do every other Saturday and she saw the paper detailing the project because it fell out of my bag. She ended up reading it and seeing how I had changed some of the sample questions to apply to my stepmom instead of my mom, and she started to get really upset.\nShe said it wasn’t right of me to include Mel in a project specifically for mothers and their daughters, and that Mel shouldn’t have made herself a maternal figure in my eyes because that was erasing my mom.\nI tried telling her that Mel wasn’t trying to erase my mom at all, and that I hadn’t even asked her about doing the project with me yet, but my aunt said that we were disrespecting my mother’s memory. We both left the coffee shop pretty upset, and later when I was home my aunt ended up texting my dad and blowing up at him for allowing his wife to take mom’s place in my life. Mel even sat me down this morning and told me that she would never ever want to replace my mom.\n\nI feel awful for all of this. I wanted to include her in the project bc I love her. I didn’t mean to make anyone feel bad. Am I TA for wanting to do the project with Mel?", "prompt_sha256": "1fe3a3d6ac10630bca878e89e684a827db1fa0ebe41185af3f5c3dce2b846610", "body_sha256": "3b6b93f7c068680ae0d20cbecf9a49113311ee7c6462f876d9b6f5ffc99eda39", "word_limit": 61}, {"stimulus_id": "P053", "submission_id": "15sbold", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nHey Reddit, I need some honest opinions here. So recently I (19F) got pregnant (I'm 11 weeks now) and so far the only people that I had told (before this whole situation happened) were my best friend (20M) and my parents. I was planning on eventually telling our entire friend group altogether the next time we hung out. Well, about a week ago my best friend told me that he's going to propose to his girlfriend who is also in our friend group. His idea was really romantic and thoughtful, and I am so excited for them. He has been apparently planning it for months and he told me he's going to propose to her during a picnic and also invite everyone in the friend group to be there as well. Here's where things went south though...\n\nSo a bit of explanation about my mindset before I say what happened. After he told me he was going to propose to her I started thinking what people would think about me if he proposed to his girlfriend and I soon after that told all of our friends that I was pregnant, which I was already planning to do very soon. I was thinking everyone would think I was trying to take the attention away from our newly engaged friends. So I figured the better alternative was to say it first, before he proposed.\n\nSo the day of the proposal arrives and we (our friend group) lay the picnic blanket down and start chatting and eating at this beautiful park that my best friend chose for us to go to. No one knows about the proposal except for me and him. I see my best friend stand up and I can tell he's about to get down on his knee so I say \"I have some news to share with you all\" and I tell everyone I'm going to have a baby. Everyone except for my best friend smiled and congratulated me. We spent the picnic talking about my plans for my baby shower and what the nursery would look like and yada yada, and my best friend was quiet almost the entire time, looking at me with a grumpy expression on his face.\n\nLater he texted me telling me that I completely ruined his proposal and asking me why I would do that to him. I gave him my reasoning, telling him I did it as to not take all the attention but he responded that I did take all the attention. But I didn't because soon he is going to propose to his girlfriend and he will be the new topic that everyone is talking about. If anything I believe I did him a solid. He called me a bunch of colorful names and said he is considering cutting me off for what I did. AITA?", "prompt_sha256": "ab156d78a0ed8a7746ab41d709053c07830acb72bbb5d63a7aa9f21ca2b5e426", "body_sha256": "8db0d22cb7ebebfef55460ba0476dd0679541c5261fc3b6d1ee8708fbb996dca", "word_limit": 61}, {"stimulus_id": "P054", "submission_id": "13mdzxw", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nMy wife and I have pre-teen triplets who we take on vacation every year.\n\nCritical information is that while we share finances, she makes about 3 times what I do and we (or more accurately she) uses her bonus each year for vacations. She is happy to do this as far as I know. \n\nThis year I suggested Colorado. Not only is it one of the most beautiful areas in our country, but I happened to be stationed there many years ago. Also, it would provide me with the opportunity to spend time with, and possibly say goodbye to one of my closest friends who has stage 4 liver cancer.\n\nI expressed my wish to spend some quality time with him as she was booking the trip. She stated we weren't going to fly all the way there just to hang out at his house and planned many activities for the week. \n\nWe just got home from this trip and due to her scheduling activities for the vast majority of the time, I got to see my friend cumulatively for less than half of a day. \n\nAnd to clarify, she would not have been comfortable taking the kids to any of the activities without me.\n\nHe just texted me to thank me for visiting, but expressed some frustration that we had so little time together. I shared the same feeling, as it may be the last time I see him.\n\nWIBTA for telling her I'm upset that she didn't allocate more time for me to see him? I'm already question myself because we went on \"her dime\".\n\nETA - he has an in-ground pool and stuff in his back yard, so a day or two there wouldn't have been \"boring\".", "prompt_sha256": "6bf1277d16f2d9e8abb5c8d0b49a258eda65ded95d9c1b23e5f09c570c20b1a2", "body_sha256": "c079e0bd9d9bdc749a0ccd4715b7378552fcf27b599a0e21f4c1347414968d49", "word_limit": 61}, {"stimulus_id": "P055", "submission_id": "upn4ht", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\n\nThe title sounds bad but please hear me out. \n\nI (16M) have a best friend (15F Ella) who has been sent weird comments by a guy (16M Dave) \n\nMe and Ella met some people back in 2020 in our city from another school and a little later we started meeting up with these people on the regular. It was a pretty big group, and Dave was part of this group. Around this time Ella was really into cosplay and she’d cosplay many anime characters, in the best way I can put it is all these characters are girls popular amongst male fans. You can kinda imagine what it is. Now something I have to mention is Ella is a lesbian but she is very feminine, so she enjoyed cosplaying these characters regardless. The issue starts because Dave starts jokingly calling her his “Waifu” whenever we would meet up, it would make Ella uncomfortable but she never said anything to keep the peace in the group. The comments started increasing and Dave would start dming Ella about a year later after all this. In that year at one point Ella kept making polite remarks saying she does not like men to sort of keep him at bay but nothing. She hates confrontation and simply decided to suck it up to not lose the rest of her friends.\n\nFast-forward February of this year and Ella decides to block Dave everywhere and stop hanging out with the group. We had already sort of drifted away from everyone else for irrelevant reasons and she decided to just move on. During this time I started going to parties and gatherings were Dave was. He was at almost every single party. He came up to me at 1 and said something along the lines of “Dude I def made Ella question.” After this I kept my distance. Another time, I heard him talking to a friend who was telling him that she wasn’t interested in him and that she was a lesbian and he said “Just wait till I catch her off guard.” from that day on I didn’t interact with him and just ignored him.\n\nOne day I was at a party he was at, and he came up to me and said he was going to my school and that he’d finally make Ella his. I told her everything and she was mad. She told me As soon as she sees him she’ll say everything she’s wanted to say all along. I was ok with that but I realized if she did that it would put my connections with him at stake and I didn’t want that. If that happened his friends wouldn’t hang out with me again.\n\nI told her and she was angry. From now on she’s been giving me the silent treatment and all my friends in our group have sided with her and haven’t spoken to me. I’m starting to think I didn’t do the right thing by protecting him because of my connections, so please let me know AITA?", "prompt_sha256": "77da95c766cca6668cac74f1413bb191444580775797b9d0c8f3e7282d225476", "body_sha256": "07e7bd254d79ed472cf826c8fcab9f88662b25fab35290feac0e0ccea17cc9d7", "word_limit": 61}, {"stimulus_id": "P056", "submission_id": "vivygh", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nI female 24, have an older sister “Sarah” (33), for years growing up Sarah has always thought she’s better than everyone, she has a group of friends that she likes to talk a lot of crap about but then be nice to their face. \n\nMy partner (m26) and I have been dating for 5 years, we are in no way financially ready for being engaged/married as we are saving for a house that we’d like to buy. \n\nwe were all at a family dinner at our grandparents when Sarah decided to kick up about how my partner hasn’t proposed to me (we have spoke about it before) and that she thinks it’s time that we start settling down to have a wedding and children, I told her that we were not interested in that right now as we had plans — she began to act like my 5 year old nephew, stomping her feet at the dinner table, she had made the remark saying that she only wanted to see if our wedding would be better than her own wedding that she had 3 years ago. She likes to compare things. \n\nRecently I had decided to throw a dinner for friends and family, everything was going well, everyone was getting along. While I was in the kitchen making food, Sarah decided to come in and “help me” by leaning against the side while I prepared vegetables for our meals. I was enjoying the quiet until she turned to me and said that I would make such a cute couple with my good friend, and that we would look so good together, this had taken me back asking her what she had meant by this, her reaction was to snicker and say “I meant what I said” indicating that she wanted to start something in my own home. \n\nI decided that enough was enough and told her to get out and not to come back, when she left with my brother-in-law my parents turned on me saying that I had overreacted and that it was only a joke and that I shouldn’t take it to heart. AITA for kicking her out?", "prompt_sha256": "98b6ce9c718967f7e67a1d1b4812b57d577eed4ffd381781de1954aa78bf2995", "body_sha256": "734dff2ecb45806dcc40fa4795e67f0fa0ba3742c47750c1b64050f73ffb4ba0", "word_limit": 61}, {"stimulus_id": "P057", "submission_id": "1ititx6", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\n  About once every week (or every two weeks  depending on life factors) I smoke half or so of a pre -roll on my apartment’s patio. I only ever have dispensary bought pre-rolls, and I never buy any flower itself. \n\n  Usually I will smoke between midnight-3am, and never earlier than 11PM, to avoid bothering anyone with a smell that can definitely be strong and putrid to some. I’m usually outside for 15-30 minutes maximum, and I barely finish half of a pre-roll before I’m at a level I’m happy with. After smoking I will spray a spurt or two of Ozium which to my nose clears the smell, however I know that I’m probably used to the smell. \n\n  There is another unit with a patio directly above mine. One night a few weeks ago I was mid-smoke at about 2 am when I hear my upstairs neighbor ask me to smoke somewhere else as they have their patio door open (The weather was nice for once). I replied “sorry about that”, as it kind of shocked and startled me. I heard a slight annoyed groan and heard him then slam his door shut. \n\n  I put it out immediately and then sprayed some ozium and went inside. I’ve been too nervous to smoke since, even though I had done it for at least a year without ever hearing anything. I have no real way of telling if my upstairs neighbor has their window open or not, the way the building is shaped the only door is their sliding glass patio door directly above mine which I can’t see from my unit. \n\nI’ve thought about leaving a note so I could talk to my neighbor personally about this, and hopefully come up with a compromise of sorts (i.e. he just texts me when he wants to have his windows open, not to ask me but just to tell me) but I’m slightly nervous since he definitely seemed to be aggressive from the way he talked to me. \n\n  I’ve also thought about just smoking again on a night with temps that most people wouldn’t have any windows open. \n\nAITA for this? Could or should I be doing more? I don’t want to be inconsiderate to my neighbors, but I enjoy smoking once every so often, and I feel I have the right to that in moderation. ", "prompt_sha256": "1eeb7726a553278802e77b19f16f2b7967e9942bdd910711cb6ca9a2688b81c2", "body_sha256": "aa5d7387394642d5e1daed30b0ca48ba83ff24e437f2a921fe2e17f3a327a421", "word_limit": 61}, {"stimulus_id": "P058", "submission_id": "g4u5t7", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nAm I an asshole for pushing a ladies dog with my foot?\n\nThis is my first post ever! So In my hometown there is a specific restaurant I really enjoy going to even when I’m alone. It is a sit down restaurant with a laid back atmosphere, anyway at the time I was with 2 of my buddies. I am severely asthmatic and with this condition comes extreme allergies that affect my body in more ways than just sniffles. If I get bad allergies it makes my lungs swell then all of a sudden I cannot breathe and have to go to the hospital. Anyway my worst allergies is to dogs and while they are cute I’m just extremely allergic to them and cannot be near them at all. So at this restaurant some lady walks in for pickup and she had a dog(big dog like really furry idk dog breeds well) and my buddies asked if they could play with the dog and the woman said sure. I stay seated and make no indication I want to touch the dog when it starts to come up to me (this dog is young too and very hyper it just jumped up on my friends too) so instinctively I put my foot up to block it from getting to me and I pushed it away with my foot gently. The woman yells at me saying not to kick her dog and got all flustered, even my friends say I was a dick and should never do that to a dog. I’m just confused. Am I the asshole?", "prompt_sha256": "c492768585990545448e1fe2a2665383dd1b553731dc09c8dd498a84acbc9d14", "body_sha256": "afc504e4c0ba03f8c365065ae2cda3f38181cc55c83dadf7f702e82279aac25b", "word_limit": 61}, {"stimulus_id": "P059", "submission_id": "16rbiwm", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nHi all, this is my first post here. My partner and I went to an art fair this afternoon that was very cute and fun. We bought a couple prints and earrings, and my partner suggested looking at this one vendor who sold pastel earrings. They wanted to buy me some, but none of them were really what I wanted, so I passed on them. We went over a second time by my partner’s request to look again and see if I wanted any. Again, I said I wasn’t really feeling them and we moved on. After walking around through some other shops and getting snacks, my partner and I walked back to the fair where they said “Now this isn’t negotiable, I really want to get you a pair of earrings from that vendor”. Thinking they were joking, I once again said that I wasn’t feeling them and we walked back to the car. They didn’t seem upset at first, but as we drove home they said that it wasn’t about me, it was about them buying me a gift. They compared me to their parents in that I shut them down after they said it was non-negotiable, and that I didn’t let them do something they wanted to do. Then they were silent the rest of the way home, and are now in their room with the door shut. We were having a great day up until this moment, and I want to know if I was in the wrong for telling them that I didn’t want the gift. Should I have been okay with them spending money for me on something I didn’t want?", "prompt_sha256": "254af74bca6a57cd30fecd4cd2cb5cc47a62db81550fea37cc95a86855bf0317", "body_sha256": "4c14e579486b77160f79070a9223565090d4c1aea8877a590628e4848220155f", "word_limit": 61}, {"stimulus_id": "P060", "submission_id": "ghfs1j", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nMy parents and extended family are extremely physically affectionate, and it makes me extremely uncomfortable even when it’s the smallest thing. When someone touches my arms or my head without warning I start trying to get them off me, and I naturally flinch away when it comes to my legs and back. I’ve told them many times I don’t like being touched but no one really takes me seriously except for my cousin. Sometimes if something feels like it was too much it sends me into a minor panic attack or just makes me cry when i’m alone and think about it, and I can’t sleep because I feel like someone’s trying to ‘get me’ if that makes sense.\n\nI’ve been told by my dad this makes my family feel bad and unless i’ve been s/xually ab/sed, which I’m very fortunate to have not been, I shouldn’t be reacting this way, and that I shouldn’t be so uptight about physical contact and just tough it out. I don’t know what is wrong with me, and asking a therapist hasn’t been any help. Am I the Asshole for wanting to tell them to leave me out of their touching and hugging?\n\n(This is my first time actually posting on reddit, sorry if I did something wrong lol, I normally just browse but I wanted to see if I could get outside opinions on this since it’s been bugging me for a while)", "prompt_sha256": "048a1859f4e048decc08ab0d48063bed8f2a62b8ce45e6c9378ae0d2efdd0408", "body_sha256": "5d5ee0ca6c33dc3e51e0a18d26089dd66c933f2fd30c9fc0a4c1c4f32f65dff0", "word_limit": 61}, {"stimulus_id": "P061", "submission_id": "k5x6ub", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nMy ex’s family are wealthy, and each child/grandchild gets a trust fund. His grandfather is very conservative though and doesn’t consider illegitimate children as part of the family. So, when my ex and I found out I was pregnant, he insisted we tell everyone we had gotten back together and were engaged. \n\nHis family still weren’t happy since we weren’t married but my ex has always been his grandfathers’ favourite so our son got all of the benefits any other (great)grandchild would get. \n\nMy stepsister mentioned how shocked she was my ex and I got back together since I had told her I hated him after we broke up and I admitted the truth to her. We were close so I didn’t think she would tell anyone else. Well, she went and told my ex’s family and now they’re angry at both of us. They obviously think I’m an AH now and have been very vocal about it. My ex’s grandfather also isn’t talking to him now and my ex is blaming me, so I feel bad.\n\nAITA?", "prompt_sha256": "ef63dcc0707ce5b3209c13d237bb4733ac7876fd5289d0262ef6991abcfad78f", "body_sha256": "cc377738942bdb56bcc0ba84d49b33c18360ea566e75eef315c0bef6c79e37cb", "word_limit": 61}, {"stimulus_id": "P062", "submission_id": "kqf3ro", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nThrowaway.\n\nMy nephew, Max is 17 years old. He's my nephew (24 here btw) and I love him dearly but he is a bit of a spoiled brat. He goes through phases like all kids/teens do and seems to have a different interest every month. A few months ago, it was reptiles. He'd stayed with me whilst my sister was in hospital (all fine now) and got really fascinated by my animals, in particular, my red footed tortoise, Daisy.\n\nHe begged his mum to get him one and eventually she gave in. Three months later, Max had a baby horsefield. He was so into looking after his tortoise for about a month and then I'm guessing the novelty wore off. From what I saw on the pictures he'd post online, the little guy didn't have a UV light. His heat lamp also broken after a month which Max never bothered to replace. I got a bit worried and spoke to my sister about it. I explained the importance of the lighting in his enclosure and also brought up that the table he was in looked a little small, even for a baby tort. My sister is not a heartless person so she warned Max that if his behaviour didn't improve then she'd be giving the tortoise to someone who would look after him, she did pay for him after all.\n\nMax's behaviour did not improve. He wasn't spot cleaning the enclosure and had to be reminded to feed him. Eventually my sister had enough. She wanted to give him away to someone that could take care of him properly. I had a bit of room in my place and I still had Daisy's old table (I'd been hoping to buy another tortoise myself) and long story short, I took him in, I payed my sister the money for the tortoise but not the enclosure as I already had my own.\n\nLast week, Max texted me and asked for his tortoise back. He told me he'd done more research into tortoise care and that he was ready to take his tortoise back and to his credit he had done his research from what I could tell. But I refused. I do get that he's done his research but I don't trust him. Besides, I've already paid the money for him. Max and a handful of family members are accusing me of stealing  the little guy from him and some others have asked me to just give the tortoise back to avoid any drama.\n\nAITA?\n\neta - Thank you for all the support you guys. My internet went out last night because of the terrible weather so sorry for not replying to a  lot of comments. I don't generally take a lot of photos of my animals, or photos in general, so I can't post a picture of the little guy right now. He's burrowed down into the substrate right now but I'll try to get a picture of him for you guys when he wakes up :)", "prompt_sha256": "f0daf543661cadd3a2b28c6c8c59e97ba501522d690deb323a02d4d6d90d61e6", "body_sha256": "c8d568e4abade37bcb9c98adceb7e1a1bdafb2d71e15fee1797c58abc979d2f2", "word_limit": 61}, {"stimulus_id": "P063", "submission_id": "rgaowv", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nMe (f24) and husband (m27) had a new neighbour move in next door in June of this year, a single mother 'May' with two young boys (4 and 7). I don't know too much but know it was a bad situation so we offered to lend a hand whenever she needed, doing the occasional babysitting and school drop offs/pick ups, grocery shopping, etc. I am a SAHM with a 2m but recently had a baby at the beginning of December so had been able to help out until the end of my pregnancy. \n\n&amp;#x200B;\n\nWith Christmas approaching, I asked if we could buy the boys a present (last year she didn't have enough money so didn't celebrate and didn't even tell 4m it was Christmas). She said yes and was excited to celebrate Christmas, we even lent her some Christmas decorations. I got the two boys some Harry Potter lego, gift-wrapped it, and had my husband deliver it. \n\n&amp;#x200B;\n\nLast weekend the boys came over really excited and were thanking me for the Christmas present. I asked them how they like it and told them why I picked it out (my nephew 7m has them and liked it) but 4m got confused and said their mother got them the lego and said I gave them clothes. I was a little slow (I blame baby brain and sleep deprivation) but my husband took over and 'saved it', claiming we knew they'd be more excited over toys than clothes. They didn't seem to question it before leaving and I forgot all about it.\n\n&amp;#x200B;\n\nThe next day May came over furious and began yelling about how I ruined her children's Christmas and had a white saviour complex and wanted all the credit and attention (they're black/mixed). She told me I should've never assumed she'd tell them I got the gift and claimed I did it on purpose getting such a 'good and expensive' gift. She said I should've given her all the credit and I tried to explain I didn't know and once I did we backtracked, but apparently 7m knew and now 4m did as well. I apparently should've known and wanted to give credit to her without her asking, and me not doing so 'said something about my character'. She was furious when she left and we haven't spoken since but it's been weighing on me ever since.", "prompt_sha256": "2488812e9238c4b7ef757db7fff4921776768a59a5f28c53b824a4dc42a33cd7", "body_sha256": "95853fc53f0c6ca4b1231516d562d3470299bebdb83c8951bb4eaf9c3cee3b93", "word_limit": 61}, {"stimulus_id": "P064", "submission_id": "157n0o2", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nMy wife and I have a son that just turned 1 two days ago. We decided to celebrate by baking cupcakes and taking him on a stroller ride in the park where we had a picnic and some playtime/walking practice with our son. We chose not to get him any new presents, considering he’s only a baby and our house is bombarded with toys and clothes, and there’s nothing he really needs at the moment.\n\nMy MIL insisted to come with us so we let her, and she gifted him a $120 giant wooden activity cube. We appreciated it very much, even though it’s kind of obnoxious lol. We think he’ll play with it and enjoy it when he gets a little older if not now, and it’s all one piece so we don’t have to worry about lost pieces. We thanked her for the present, and then she asked us what we bought for our son, to which my wife said “we decided he didn’t need anything new, so the fun time and the cupcakes are his present.”. My MIL absolutely flipped out about this, saying that we “didn’t love or care about our son” and that we were “selfish negligent parents” for not buying a baby brand new toys that he didn’t need and will probably never play with. \n\nAs if that wasn’t bad enough, she started passive aggressively talking to us through our son, by saying to him in a baby voice, “do mommy and daddy not love you enough to get you new toys?” “You know that grandma will always buy you toys…”, etc. This made us both very angry, and I told her to stop talking to us though a baby. She continued to call us terrible parents and trying to make us feel guilty for not buying a baby who doesn’t even know he exists yet, new toys that he’ll never play with. \n\nWhen our son gets older, obviously we’ll buy him new stuff. But we didn’t feel that it was necessary this year because he loses toys so quickly and doesn’t even play with the ones he has. His favorite toy is a plastic bottle anyway. \n\nMy wife finally said “if you’re going to talk to us this way, you can leave. And if you don’t leave, we will.”.\n\nWe were sick of arguing with her, so we packed up our things and left. My MIL keeps texting me and my wife and trying to ask if she can babysit our son, and we haven’t responded. \n\nAITA?", "prompt_sha256": "8c2fe33d86552527b6815ccf6ad2d56d4b7867125e8c099ebc509b7794ad69c6", "body_sha256": "a4896a877e1a737ddc873cc09fd8d4e0ec4daf2856ce9d78768e402f4d2b47ac", "word_limit": 61}, {"stimulus_id": "P065", "submission_id": "xyy8zd", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nI(28F) am white and is marrying a man(31M) of Indian descent. To respect both family’s traditions we are having two weddings. Me and my fiancé are splitting the budget for the white wedding and the Indian wedding is being paid for by his parents on their insistence. Originally we were supposed to have the white wedding first followed by a traditional Indian wedding. Now, that the wedding is less two months away, my MIL informs me that she had to prepone the Indian wedding because some people from her side of the family can’t attend anymore on the original date because of some issues making it take place before the white wedding. While wedding planning, I was told by my future MIL that during the Indian wedding I have to apply mehendi ( a sort of temporary tattoo) on my hands. I said okay. The thing is, if my Indian wedding happens before the white wedding, I would have by hands covered with the temporary tattoos and it would totally clash with my wedding theme, so I informed my future MIL that I do not like the idea of having the mehendi put on anymore. She was upset to say the least and also implied that since she’s paying for the wedding, she should have the right to decide. She said I was disrespecting the customs and acting ignorant. I talked with my fiancé about it and even though he didn't say it outright, I know he agrees with his mother. My friends are divided. Some think that I am right to want a specific aesthetic while others think I’m being worrying over nothing. I have had little to no say about what happens at the Indian wedding so I really want the white wedding to be exactly how I want it.\n\nAITA?", "prompt_sha256": "20954f1a284b4191fd2dd09d387fa16f2b889ef640555418d70bb3e6d4d669f0", "body_sha256": "d443d160b784c7323ea9a168839a1e731df49db468ee105140168d986ce683f0", "word_limit": 61}, {"stimulus_id": "P066", "submission_id": "nj91d3", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nContext: My \\[16m\\] aunt and uncle are divorced, my aunt lives abroad and my uncle is very ill in hospital. My cousin “Lucy” \\[18f\\] is an only child. My parents are also divorced, my brother “John” \\[14m\\] and I live with our mother. Staying with my father is not an option. John has aspergers. John and I each have our own rooms. \n\nSituation: While my \\[16m\\] uncle is in hospital, my cousin “Lucy” \\[18f\\] will be staying with us. However, we - my mother, brother “John” and I - live in a small bungalow with only three rooms. My mother works shifts and John is very particular about having his own personal space, so my mother wants me to share my room with Lucy while she is here. I have no personal issues with Lucy particularly but I am uncomfortable sharing my room with a teenage girl. The lack of privacy concerns me. My mother says it shouldn’t matter because ‘we’re family’ but it still makes me uncomfortable. I know that this is a tough situation for everyone and that it probably won’t make a great impression if Lucy is asked to sleep in the living room, but we don’t know how long she’ll be here for and I like my space. AITA for not being willing to share?", "prompt_sha256": "f6a260ebf6cf4728f557650dc622ad716b61ed3e1d58a52c24a9b56a7d8b98e6", "body_sha256": "80564b5a63acd36887f9c27b904798d48198c216f38a3381d1dc65d2f2871e85", "word_limit": 61}, {"stimulus_id": "P067", "submission_id": "y2ghqw", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nEdit: thank you all soo much for your words &lt;3  \nseems like most of you are saying i should sit down with them and discuss what happened/my boundaries and i totally agree. hopefully we can do it tonight  \nagain, thank you! (original post below)\n\n&amp;#x200B;\n\nthrowaway, my family uses reddit + monitors my account\n\nMy (15F) parents got divorced almost 5 years ago. I'm very close to both of my parents and it was devastating, but I understand why it happened. I stay with my dad on weekdays and with my mom on weekends as my mom didn't move too far; they're both on good terms.\n\nIn that time, my dad got married to my step-mom, let's call her Emma, when I was 12. E is the daughter of my grandpa's friend on my mom's side... if that makes sense lol. She stayed at our house a few times, we got along... only okay.\n\nAfter the wedding, Emma moved in with her daughter. Despite me being not thrilled at first, this turned out to actually be a good thing! Emma is very nice to me and her daughter isn't too bad either, despite me not being too fond of kids. Turns out, we just needed more time together to really bond and form a good relationship.\n\nHowever, things took a turn a few days ago when I invited two friends over. She welcomed them and introduced herself as my mom. I corrected her and said she was my stepmom and her smile fell. She once again called herself my mom and I corrected her, again. I ushered my friends to my room and then came downstairs to talk to her about it. She asked why I corrected her and I said it was nothing against her, but I already have a mom. She responded that she thought she was my mom and that I had forgotten about my other one. I got defensive and said that she would never replace my biological mom. She left the room and hasn't been the same to me since. She told my dad, in tears apparently, and he was conflicted but eventually took her side. I know this because he acts angrily towards me.\n\nI meant no harm against her but she shouldn't try to replace my real mom who I facetime and text every day and see every weekend. Lately I've been feeling bad though because I don't think she did it in malice and I may have hurt her. So, reddit, AITA for correcting my stepmom?", "prompt_sha256": "c2953872413df9687894cc5b6aa07da473adbeecd11527bb80e8bbfb725d776e", "body_sha256": "dade5a2fa948c929efd24b891c94fbc02698ab14cdb1fbdfd770bbd6cc02e8a6", "word_limit": 61}, {"stimulus_id": "P068", "submission_id": "1ekz9un", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nMy roommate constantly takes advantage of me, especially financially. We are both on the lease. I pay more than them for far less space because they act as if they own the place. Last week we had an argument when they demanded I pay 80% of the energy bill because I run a medium sized fan (we have no AC). They became very nasty, throwing a tantrum and started making a lot of complaints about me and blaming me for things (I stayed civil). I am still pissed off about it.\n\nOur apartment has no guest parking. My roommate found out I rented another parking space for guests, which costs me $75/month. I have no idea how they discovered my parking space number because I don't see it on the resident portal, but now they want to use it for their guests. This frustrates me not only because they always financially exploit me, but because in the past when I give them an inch they take a mile and I don't want their guests over for hours every day. If they want a guest parking space, they can pay for it like I did. Additionally, I find it creepy that they contacted the leasing agent to find out my parking space number, as I couldn't find any documents online stating it, and they have a history of being nosy. WIBTA if I refused to let my roommate use my extra parking space for their guests?\n\n**Update:** Thanks, everyone, for validating my side. I struggle with being a pushover, but I stood up for myself and didn't let her use the space.\n\nAs expected, they're pissed off now. Like in the past, they arrange things before asking me, assuming I'll say yes. For example, they once kept scheduling visits to visit their son in jail without consulting me first, expecting me to stay in the apartment and watch her dog with severe attachment anxiety for 5+ hours regularly for free because I agreed once, not knowing the dog's issues. There are MANY crazy details to that situation... They had already planned to have their friends over and I guess it couldn't happen without using my parking space, so now they're upset.\n\nI don't know what to do if they use the spot anyway because I can't imagine the drama that would ensue if I had their friend's car towed. I don't want to escalate my living situation to DEFCON 1...the lease ends in October.", "prompt_sha256": "25bc0fe29df2458fca3a5e2a28996135b154354001d07c29deec8a1ec374e987", "body_sha256": "b6be12475b11a34cac3bc968c6fc027add58626c2759c65848895ad47a37ec55", "word_limit": 61}, {"stimulus_id": "P069", "submission_id": "z2qr00", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nMy partner and I bought a house. I do all the cleaning, I prefer to, bc well, he is a man. No offense to the males but his idea of clean is far from my idea of what's clean.\n\nWe are hosting a X-mas party for my family. My first time ever being able to, and I am very excited! I went out and bought Xmas slippers in all different styles and sizes. My partner asked why we had a huge basket of slippers by the door and i told him. I plan on telling everyone that they have to remove their shoes before entering the house, but I have slippers for everyone and they are welcome to bring them home after the party. My partner is saying I am being an Ahole bc I shouldn't expect people to feel comfortable taking their shoes off. I asked my sister what she thought, and she said I am being weird. That some people choose shoes to go with their outfit, or just don't want to take them off. That I should just get over it and let them wear what they want. \n\nI don't allow shoes in the house normally. I have 2 cats that will eat whatever is on the floor. From dirt, to fur, to leaves that blow in. And I also, just hate the thought of shit being ground into my floors. I am giving out slippers, am I really an ahole for expecting the rules of our home be followed?\n\nEDIT:: the me cleaning bc I do it better, is an ongoing joke/silly argument I have with my partner. I am truly sorry if I offended anyone with this comment. I won't delete it, but I should have just pointed out that I alone am the one who always cleans. Until he moved in with me, he never had to clean a day in his life. He does help, but I always end up redoing whatever he did. I did not mean to say a man is incapable of cleaning, I just meant MY MAN is.", "prompt_sha256": "0a8bd87a6b26b377e87cecf3a6e4d50d62a34d7179374f9b799855462acc64eb", "body_sha256": "5637e5451c6d8c7195c6151cd42b50eeb72b007a5991b67444f705f273e5aab6", "word_limit": 61}, {"stimulus_id": "P070", "submission_id": "1l0r032", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nI (36F) have recently had an argument with my mum (56F). Long story short, I have had enough of her \"helping\" me without asking first. Some of the \"help\" I received from her in the last 3 years was (bear with me):\n\n* Bringing homemade food (sometimes, we're grateful, but sometimes we've just made 3 days worth of food that cannot be frozen so we end up deciding which dish we throw away),\n* (Re)gifting clothes; gloves EVERY Christmas, oversized business clothes (I don't wear suits to work), kids clothes on sale (why would they even make white crawling overalls, have they seen a child?)..,\n* Inviting family members to get-togethers she does not host (I would be fine with them coming if she actually asked beforehand),\n* Buying baby shoes on her own after we've agreed I will choose them, because I know which ones the baby needs. The ones she bought are inside shoes, we have heated floors, they will fall apart if taken outside,\n* Buying a walker for my baby because \"she's coughing from crawling on the floor\" (beside walkers being dangerous af, she was already pulling herself up on furniture and started walking 2 weeks later), \n* Cutting my daughters fringe hair TWICE because \"she couldn't see\" (she could). The second time is really my fault because texting \"Why does my child look like Yolandi from Die Antwort???\" was not enough of a deterrent. \n\nYes, all of this is very thoughtful, yes, I know she's doing this to genuinely help me, yes, we're both control freaks, yes, we're both stubborn, but I asked can she at least ASK me beforehand?\n\nI suggested she doesn't ask because she cannot deal with me saying no and she became upset \"how can I even think that she would do something so convoluted?!\". 10 minutes later in the discussion she says \"maybe I don't ask you because you'll refuse.\" \\[??\\]\n\nAfter much crying and processing she apologized, saying she did not know this is upsetting me so much and that she will ask me going forward.\n\nThe next time I saw her she gave me a tupperware with apricot sheet cake. When I asked why she didn't ask me as we agreed, she said she couldn't and made up a reason that did not make sense. To me, she just wanted to break the promise so she could continue not taking my wishes into consideration. I was too stunned by the bold move to do anything about it in the moment.\n\nSo WIBTA if I threw away the next thing she gifts me (if she tries to talk me into accepting), in front of her? Hoping that would make the sentiment stick?", "prompt_sha256": "585c534fe4bef9776f6f8e56101d7a3b9a1a9713ed1b12e8dcb3827d20c15f65", "body_sha256": "56edea7e1605fe094ca477c7b1e88e3c450dd92d606047059176b2c4d4b59512", "word_limit": 61}, {"stimulus_id": "P071", "submission_id": "ozvkfe", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\n\nLast summer I retweeted a few anti-cop tweets on Twitter after all the chaos happening, which caused some tension between a friend who is engaged to a cop and I. We made amends and tried to remain friends but I still don’t think she’s a big fan of me anymore. She’s getting married in October and my invitation doesn’t say I can bring a plus one. That normally wouldn’t really be an issue, however all of our mutual friends who are the only people at the wedding I know, are all in the ceremony meaning I would be sitting alone. I think she did this out of spite since my friend who is also single was allowed a plus one. Am I the asshole for declining the invite?", "prompt_sha256": "2c1ded37f13c6c9b3e3792d60dc396d786bba0310be09a25c86634838510d32a", "body_sha256": "e03330d8cfffd8d589cd13a6ce768aa23d3c240fbe0472942c0be1e790b883f5", "word_limit": 61}, {"stimulus_id": "P072", "submission_id": "18ambm6", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nI (34 M) got married to Ashwathy (34 F) recently (arranged marriage). We live in the USA, but we are based in India. After Hindus have their wedding, it's customary for wives to offer their husbands a glass of milk during nighttime.\n\nShe had obviously agreed to hold it according to Hindu tradition. For those who'd say that I should've specifically discussed the matter of milk with her: no one discusses it any more than one specifically asks Christians to show up in a white dress. It's taken for granted, and it's the same here.\n\nIt was going fine until she showed up with a couple of bottles. I was wondering what those were and Ashwathy opened it to reveal a couple of alcohol bottles instead. I was shocked, and asked her what that was about. She said \"It's our first night together, so we might as well have some fun, right?\"\n\nShe offered me a glass, and I refused. She drank the whole thing down (two bottles) and then got drunk. She vomited, passed out, and I had to clean up the mess.\n\nThe next morning I asked her what that was about and she asked me in an amused manner did I not know that she's an alcoholic, and that I'd agreed to marrying her. I had no idea and asked her what she was talking about, and she said \"My parents had agreed to inform yours, actually. I have drug addiction, including alcohol.\"\n\nI was basically floored & had no idea what to say. I got really livid and accused her and her parents of betraying me, that she had never told me that & had agreed to have it the Hindu way, etc. She and her parents got mad and began to yell at me, saying that it's not my business what she drinks.\n\nAITA?", "prompt_sha256": "9294c106d4de41727f844220d24bc0948de6918d68f5202f8848431f0fca328e", "body_sha256": "e3834636b8ee20a66b8660209a76feed8732d4614fd619b2bca10697233e5d60", "word_limit": 61}, {"stimulus_id": "P073", "submission_id": "g8tpaz", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nA few months ago, me and my bf of 3 years, Ryan, went on a cabin retreat with some mutual friends. We all booked out a big cabin for a weekend retreat. There is a girl, I'll call her Lydia, who is a part of Ryan's group of friends who I don't know too well. They met at uni and according to a few of our friends that know her well, she has a big crush on Ry. Nbd because it seems like she hasn't crossed any boundaries after he made it clear that he is taken.\n\nAnyway, onto the issue. We are on this retreat and I'm not a big fan of PDA. At. All. \nSo me and my boyfriend keep it to a minimum and keep any physical affection as private as possible, minus any jokey flirtation or hand holding. Earlier, we played truth or dare and someone asked Lydia if she would get with anyone in the group. She kept laughing and making glances at Ryan which did annoy me but I decided to ignore it. \n\nLater that evening, everyone was winding down and separated off for our downtime. On the way to the toilet, Lydia and 2 other girls are in the common area having a chat and I overhear them talking about Ryan (my boyfriend) and how attractive he looked that day. I found it incredibly awkward overhearing that and left them to it. I'm confident in my relationship so it didn't bother me massively. On my way back from the toilet, I see my boyfriend headed towards the common area looking for me and I stop him in his tracks and ask him to come with me outside on the porch.\n\nOutside the cabin, there's a beautiful lake surrounded by trees. Naturally, this created a romantic mood for us and I figured nobody is around to see us alone so we ended up making out. After a few mins, I hear footsteps &amp; the front door slam. I knew someone had seen us &amp; we stopped. I went back to my room that I'm sharing with the girls on the trip. I see Lydia and our other friends gathered around her. She's crying her eyes out and I ask what's wrong. Lydia immediately tells me to STFU and \"piss off\". Lydia's close friend snaps back saying \"you didn't have to rub it in her face, we get it. *You're together*. Did you really have to sneak off with Ryan knowing Lydia is struggling with her feelings for him?\" \n\nI tried my hardest to keep it cool &amp; said that I was gonna leave &amp; we can have a chat when she's cooled off. I decided to go into the boys room and asked to stay with them for the night, sleeping in Ryan's bed of course.\n\nThe next day at breakfast, there's awkward tension. Later on, I sent Lydia a text explaining that I still don't understand what I did wrong since he's *my* bf. She ignored it. Tbh I had had enough so I decided to leave the trip early. Ry decided to join me after I explained what had happened. We then later received messages on the group chat calling us rude and insensitive again. Inconsiderate of Lydia's feelings.\n\nAm I really the asshole for kissing my own boyfriend on a group trip just because another girl has feelings for him?\n\nEDIT: Will post an update to this after speaking to my bf today\n\n--------------------------------------------------------------\n\n&gt;UPDATE: Idk if this falls under an update per se or if its more of a clarification post but after posting yesterday, it was clear that I didn't do anything wrong. It was also clear that I should get more clarity from my boyfriend on his stance about this. So I brought up the issue with him and just to outline what happened since we left.\n\n&gt;Ryan told the group chat to piss off and left w/ me. Shortly after he received a bunch of messages from Lydia's goonies (the 2 that were furious at us, but mostly me) basically berating him for not comforting her or hearing her out. They kept saying that she has mental health issues so we shouldve been more understanding and not been so \"brazen\". And they insisted that Ryan speak to her so she can \"have a chance\". \n\n&gt;Ryan, again not that confrontational but according to him he was furious anyway, told the girls to piss off once more, and that he wants nothing to do with them or Lydia again. He sent a message to Lydia (which I saw) saying how inappropriately she behaved and that he would never look her way. He understands that she might be struggling but that has nothing to do with him since his priority is me (which I was unbelievablely overwhelmed with love when I saw the message). He then told her never to contact him again and blocked all 3 girls. Other friends messaged him in support shortly after. A few friends clarified that they didn't want to get involved and spoil the rest of the trip, but it was practically too late as Lydia was still in hysterics and the rest decided to cut the trip short as well.\n\n&gt;Ryan didn't discuss it since, because he didn't want me to get affected by it but he's been just as loving and just as reassuring. He loves hard tbh. That's why I always felt so secure in our relationship. So he managed to tell me all of this last night and then I showed him the post to which he was laughing and happy that we made the right choice to leave and disengage. \n\n&gt;As for me, after we left I didn't want to engage with them or the situation any further so I left the group chat and only stayed in contact with those that immediately showed support to us. But I didn't want to discuss the issue until Lydia messaged me recently saying that *I* was immature for not letting Ryan give her a chance to explain herself. I blocked her (and her friends for good measure) right away.\n\n&gt;Tl:Dr apparently Lydia has mental health issues that her goonies think should excuse her hysterical behaviour. Me &amp; Ryan are solid as ever.", "prompt_sha256": "d4a4e9df2c11ed0c300aeb5e1f56b2a2ff666e91e253070f8acb48586d509927", "body_sha256": "5b30def54ccd4c2eb3b04a1add9b5d1a5c4961909302abba3ad621bae8c3cee1", "word_limit": 61}, {"stimulus_id": "P074", "submission_id": "spsoup", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nI (24) have received an offer from a competitor giving me almost double the money in terms of payment. At first I was wowed and excited to see the possibilities that this kind of money would bring me.\n\nI have accepted the offer and told my current employer about it last night. I work in a small company, everyone is friends with everyone, we all got our backs etc. I was hired during my last semester in college and I have learned so much from these guy whom I'll always be thankful for.\n\nThe problem is, it's really hard to find people who do what we do. We tried hiring and training a lot of people but they are either too lazy to learn and always try to work as little as possible. On top of that, it takes roughly 6 months before an employee with no experience starts contributing.\n\nCurrently, my employer has only two people he can trust fully when taking up projects. A colleague of mine and myself. The other guys in the firm are still in their training period and can't lead projects by themselves.\n\nI love working here, I like the chance that was give to me and I'm grateful for it, but the pay is not great and there's a lot of work I have to put in to get it.\n\nWhen I told my employer about it last night, I saw him almost crying, almost begging me to stay and trying to tell me how he wants me to stay. He then told me that he would rather get a loan to make me stay, otherwise, the company might go bankrupt. He was really desperate and I have never seen him like that.\n\nI don't know what to do. I feel extremely guilty and selfish for wanting to leave and I know that there may be a chance for the next job to suck, but it's double the money.\n\nTLDR: I work in a small company that might bring it to ruin if I leave. I have enormous amounts of guilt, but I'm getting twice the salary that I have elsewhere.", "prompt_sha256": "9396bff22c5d2e08c2a1d1ce5037277cd0b0d42eae16a8c39759cb583bcb1878", "body_sha256": "65307c7a6b6318cd6e04df3622fd69fbc888db9705a94624e26e78386e26ec9b", "word_limit": 61}, {"stimulus_id": "P075", "submission_id": "1f5nue9", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nI'm 25m, he's early 20s and has pretty much no experience with budgetting. Last time I was on holiday with him he spent all his money then said he'd need to borrow money to get the underground, \n\nNow, I'm not really comfortable with asking for money, and, well, he's not exactly one for paying a debt if he's not chased up on it, so he never repaid.\n\nThis time, he was spending money at an alarming rate and said he might need to borrow money for the unerground. I suggested, \"Why don't you put £10 in your suitcase and leave it there until it's time to go? That'll more than cover the underground.\" The underground isn't that expensive.\n\nGood idea right? He didn't seem to think so as he spent it all. \n\nTime to go home came, he asked if he could borrow money from the underground. I said he couldn't, he never paid back last time. He said he would. I told him he should still pay me back for last time, but I'm not lending this time. I then told him to do whatever he'd do if I wasn't there, or if I'd been as reckless as he had been with his money, scanned my card, went through the barrier and went home, him still on the other side of the barrier.\n\nHis answer seemed to be to call home, we're about 3 hours away from London so his brother ended up doing a 6 hour round trip(not including the London traffic) to get him.\n\nHis brother told me I should have lent him the money and he'd pay me back. I said that my actions might help him to remember next time.\n\nAITA", "prompt_sha256": "476cb18bc2ced3b6b1faca271831c82b91c300dc756ad34dbb5a450973feea4d", "body_sha256": "0882bb407042e8882849f777fe41e4d16c5244c7a18f67e183494cb4e310a786", "word_limit": 61}, {"stimulus_id": "P076", "submission_id": "ght2rr", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nMy boyfriend and I are planning on getting an apartment together within the next year. We both have a cat, he's had his for 8 years, I've had mine for almost 12. Neither of our cats like other cats, but his is aggressive and will attack them. She even attacks his family's other cat that she grew up with. We're going to try to keep our cats away from each other as much as possible, but I told him that if his cat hurts mine I will move out. I don't expect him to get rid of his and I don't want him to, I know how much his cat means to him and I like his cat too, but my cat is my number one priority. When I told him that he got really upset because I'm putting a cat above him. I honestly love my cat more than anything else. She's been there for me through everything and I don't know what I'd do without her. My friends have gotten mad at me because they think it's ridiculous to put my cat above my boyfriend, so AITA?\n\nEdit: I just want to clarify that I don't think my boyfriend is doing anything wrong at all, I don't blame him for being upset, and I wouldn't break up with him if I moved out.", "prompt_sha256": "36321adfd8ef17bd5fa87824bffc9823b1cf15b7fe14f46080885ae3ba93f3de", "body_sha256": "485e665168163c81c779b63a743716c2ea4f677a007bea2d0ad109d5aaaca4ab", "word_limit": 61}, {"stimulus_id": "P077", "submission_id": "kqnb7g", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nI (21M) talk to my girlfriend (19F) every night over text so she tells me what's happened throughout her day.\n\nRecently her father has been quite ill and the hospital has basically written him off saying that there's not alot they can do for him as his organs are getting weaker and weaker.\n\nShe's been getting pretty annoyed at me recently as whenever she brings up her Dad I get quite awkward and don't really know what to say and I tend to try and change subject, she says I should be more \"comforting and compassionate\" and I just don't know how to do that.\n\nIn addition to this I have High-Fuctioning Autism so I've always had difficulty connecting and communicating with people plus I've never really been in a situation where a close loved one died or is dying so it's hard for me to grasp.\n\nI'm afraid of upsetting her because she cries alot as she's prone to getting very stressed out and it just isn't in me to upset her more by talking about a subject that is as horrible as the one she's in and I strive to make people laugh but that's not what she wants.\n\nI have tried explaining to her my side but it's difficult for her to understand, however I have said I'll try to be more comforting and compassionate.\n\nSo AITA?\n\nEdit : We've been together for 3 years.", "prompt_sha256": "413bd676380c227e9a8652475ae9e63f063c945d0722dbfa8e0de759bc46a71a", "body_sha256": "8a24a1db1f8b75185d53602a532130d08148a20051d718fb6b32b0ced5cf8ede", "word_limit": 61}, {"stimulus_id": "P078", "submission_id": "f9c5ig", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nObligatory on mobile statements please excuse errors. DV stands for Disabled Veteran it's the same thing as having a disabled placard. (Fair warning it's a long one).\n\nI (35m) am a disabled veteran I don't advertise I am one but I do have my states DV plates that allows me to park in handicapped spaces. They performed a transfemoral amputation in 06 due to combat-related injuries. So I have an endoskeletal prosthesis, you, however, wouldn't know it was there unless I rolled my pant leg up. You especially wouldn't know from looking at me from the waist up. I also have a babyface when clean-shaven.\n\nThis morning I had to go to the nightmare that is wally world (Walmart) and was lucky enough to snag one of the close-up handicap parking spaces. I pull in turn off my car and before I can even do anything this elderly woman and her son pull up behind me and start laying on their horn. They were motioning at me so I thought maybe something was wrong with my vehicle and they were trying to signal me so I got out of my car to check with them. \n\nThey roll down their window and the son starts yelling you can't park there that's illegal if your handicapped person isn't with you you need to move. The mother chimes in with this whole shame on you for using someone else's benefits (not verbatim). I say sir I have every right to park here as I am disabled. I pointed to my DV plates to emphasize this. Then he yells (yelling bc of the motor running I assume) even if you have some disability (that tone where they don't believe you) it's pretty clear you have no issues walking what the fuck ever. His mom adds you're younger than me the right thing to do is for you to give up that spot to someone who REALLY needs it. \n\nAdmittedly my temper was starting to get up so I said. Ma'am, sir if you fucking think I broke the law call the fucking cops I will gladly wait for them to sort this fucking shit out. If you don't want to do that then you can fucking pound sand I got here first so fuck off. I leave and go inside thinking it's over. I'm in the store maybe 20 mins when the woman and her son come up with a Walmart security guard and a cop. And they start interrogating me in the aisle asking if I had accosted the lady and her son. I start trying to tell my side of things but son butts in saying he doesn't look disabled at ALL. \n\nI'd had enough so jerk up my pant leg so they can see the lower part of my prosthesis and say is this disabled enough? The security guard apologizes but adds well you should have just shown them, to begin with instead of being an AH about it. I was so pissed off I just ended up leaving the store, now that I've calmed down maybe I was the AH here but my wife says I wasn't and that security guard and everyone else was in the wrong.\n\nEdit: for context, the cop never spoke to me I assume he was there to make sure things didn't escalate. After the altercation though as I was walking away the cop spoke to the security guard. For all, I know he gave him a come to Jesus talk.\n\nEdit two: To be fair the lady was using a mobility scooter.\n\nEdit: because it keeps coming up. 1.) In my state, DV can park in handicap spots without the hanging placard. It's a state to state thing.\n\n2.) Some days I do have trouble with walking and pain. There is no way to predict what days I will have PLP (phantom limb pains) walking further distances tends to spike it. Then it can last a few seconds, a few minutes, hours. I also have extreme lower back pain that when it gets bad enough I have to use my cane. These things are never entirely alleviated by the shorter distance but it does help.", "prompt_sha256": "0b20c534076d3cee9413415bfceeb09c145a2afe19a4ab301590495fffd6611b", "body_sha256": "6e0ae1055499caae81ef959109db12d3a8bb530271fd9c1e38ca83bed296610e", "word_limit": 61}, {"stimulus_id": "P079", "submission_id": "iywr5a", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nI never wanted children. I was always careful, always wore a condom, but somehow I ended up getting my ex pregnant. I begged her to abort or to consider adoption but she wanted to keep the pregnancy. We ended up moving in together and        I met my wife around the same time. We were in the same friend group and I was instantly very attracted to her, I guess people call it an emotional affair. I told her about my problems and she was supportive and believed if a woman could abort, a man should have the right to walk away.\n\nMy ex gave birth to twins and I stayed for the first six months, but honestly I just didn’t love them. I didn’t want to be a father, the feelings weren’t there, and I was becoming very depressed. I hated my life and I think if I stayed I would have ended up severely depressed or an alcoholic. My wife graduated around that time and was moving back to California (we were in New York, so across the country) She said I should come with her and start over. She said something that really stuck with me about how if I don’t walk away now I can’t do it in five years, and right now is the moment to hurt my kids the least.\n\nI told my ex that it wasn’t working and I didn’t want to be a dad. I move to California and married my wife, but I paid all of my child support, paid for their education, extracurriculars, etc. when the twins were eighteen they wanted to meet me, and I felt ready. My son and I built a good relationship but my daughter hates my wife. She wants her to apologize for telling me it was alright to leave, which obviously even if she did say that, I made the decision.\n\nMy daughter is getting married and recently said my wife is not invited. I told her that is incredibly disrespectful and you can’t invite half of a couple. She said she is selfish and evil and just said those things so I’d move with her. I’ve fully paid for this wedding, which I probably wouldn’t have if I knew this ahead of time, but I told her I will not publicly disrespect my wife.\n\nEdit: I am deleting this account but someone told me that people are looking up the user name and harassing some lawyer. My wife is not a lawyer. Please, you can think i am a mega asshole, but leave that woman alone.", "prompt_sha256": "584162feef2f2d48d09940845f538808049d51c8efc79c17bb3b06dfb5c5ccb6", "body_sha256": "bff25dd7cf85e69e977173cfffe294e53ececeb50b7304434a3937157efdb4bb", "word_limit": 61}, {"stimulus_id": "P080", "submission_id": "r2t157", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nPseudonyms and throwaway for obvious reasons.\n\nMy (25M) grandma tragically passed away about a month and a half ago. She raised me and my brother, Daniel (23M), after our parents passed away, so she was more like a mom to us than a grandma. Her death was devastating to us both.\n\nIn an incredibly unfortunate insult-to-injury, my wife, Anna (26F), was badly injured in a car accident a few days before the funeral. I’m relieved to say that she suffered minimal permanent physical trauma and is due for discharge soon, but when the accident first happened, she was in critical condition and nobody knew whether she was going to pull through or whether she’d be able to walk again. By the time of the funeral, my wife was (mostly) stable, but I was committed to being by her side in case something happened to her. As much as it breaks my heart, that meant missing my grandma’s funeral. To say the least, my brother and extended family did not take kindly to this.\n\nA day after the funeral, I posted about Anna’s condition and received a very mixed bag of replies from my relatives. While some were sympathetic, the consensus at large was that it was disrespectful to miss my grandma’s funeral.\n\nDaniel called me up later and said that he hoped Anna was doing alright but that he was angry with me for missing Grandma’s funeral. He started ranting about how paying my respects was the least I owed to the woman who raised me.\n\nHere’s where I screwed up the worst, in my opinion. Bear in mind that at this point, I’d barely slept in the last seventy-two hours, my brain had not even gotten the chance to truly process the death of my grandma, and there weren’t even any guarantees that my wife would make it through the night, let alone walk again. I was emotional and exhausted––and I snapped. I told him that funerals were for the living, and that I’d never forgive myself if Anna died in the ICU with nobody around her just so that I could pay respects to someone who wouldn’t be helped by it.\n\nI understand in hindsight how disrespectful it was for me to say this. It was not my proudest moment by a long shot, and I’ve apologized for it many times since, but as I said before, I was at a loss. Daniel told me that I was a terrible grandson, and later posted some passive aggressive Facebook status about respecting the dead that was clearly directed at me. Neither him nor most of my relatives have spoken to me since the funeral.\n\nSo, Reddit, am I the asshole?\n\nTl;dr: I missed my grandmother’s funeral to stay with my wife in the hospital after she was in an awful car accident. My brother was very upset about this, and I tried to justify my actions to him in a disrespectful way. Neither him nor my relatives are speaking to me now.", "prompt_sha256": "9dce99e4bfb9cffd5965a220ff67f19709f724a266a62fda373a6f39bcd61895", "body_sha256": "0ee60a6eabe7bf7e2faa3bdeaaa59d874e9a725c5b50c901c755988594646e2a", "word_limit": 61}, {"stimulus_id": "P081", "submission_id": "zf3v7b", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nEdit: I would like to thank the folks who actually responded to the question without making assumptions about happenings that were not described in the post. I found them helpful and will consider some of the suggestions offered. Just to clarify though, at our house it is not uncommon to take whatever car is sitting at the end of our driveway. Although we usually all make the effort to ask, she didn't and that was my reason for opting for this as a possible punishment. My son thought it was really funny you all wanted her charged with theft!! Lastly there are too many nuances around her 'accidents' to fit within post limits but she is not a menace on the road. This was also not the only consequence she is to face, it was one of a list that she fully agreed to and accepted.  \n\nMy daughter (E22) took w/o asking my son's (P21) car to run an errand. It was raining, she hydroplaned into a fence and totaled the car. This is her 3rd car to be totaled, 2 her fault and 1 the other driver's fault.   All the cars are in my name and were purchased by me and hubs. We also pay all maintenance and insurance. She is offering her savings of 10k towards replacing his car but with the cost of cars an equivalent will be upwards of 20k and insurance surely won't pay out enough to cover the gap in cost.\n\nMy hubs and I share a car. It's a 13 yr old car with 220k miles. It's in decent condition just approaching end of life for a car. We planned to buy ourselves a new one with his next bonus in March. If we replace my son's car, we won't have the money to replace our car.\n\nWe are considering giving my son her car, giving her our car and going ahead with purchasing us a new car. We would continue to maintain all the cars and insurance for them.\nWhen all of these accidents come off her record (or if the older car dies), we would help her get another car. This one would be in her name and she would then be responsible for insurance and maintenance.\n\nWIBTA for taking her car?", "prompt_sha256": "bd4705543a567fca901cee9aa9f9f4a43f970c5ffa51ddf71603f1eb5cfd22d5", "body_sha256": "d3b269e9a268cb33226e1955d2c892f7ff5fbb81cdd4e86853f8e1c03b7f67a5", "word_limit": 61}, {"stimulus_id": "P082", "submission_id": "14c6rfw", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nMy mom (39f) and I (23f) were going grocery shopping when my dad (41m) texted my mom and asked if she would buy him cigarettes as he had ran out. \n\nShe said she would but then realized that she had left her ID at home and asked me if I would buy them otherwise we would have to drive all the way back home for her to get her ID. \n\nI told her no thats the 1 thing I'm not gonna do is support his smoking habit we have lost a lot of family to cancer and I'm not gonna help him into a early grave.  She got mad and upset and I got yelled at by my dad once we got home he called me a dick and told me it was a dick move since \"your mom does so much for you\". \n\nBoth of them know I feel some type of way about him smoking so I have no idea why they thought I would be ok with buying cigarettes for him. Besides that they honestly don't do a whole lot for me just the bear minimum meanwhile I do the laundry for them wash the dishes 90% of the time take the trash out and feed THEIR dogs. \n\nAnytime I have asked them to do anything for me they either say they are gonna do it and then don't or get offended that I even asked and say no.\n\nSo amita?\n\nTldr: won't buy my dad cigarettes they got mad.", "prompt_sha256": "cef18d4046d03ff48058235424af81cb99dabb4e2bfc24491a0639db1002baa9", "body_sha256": "4a78b34545e1f935851c35291a58c222083e9288220dd96486c0e0fee76e9a0b", "word_limit": 61}, {"stimulus_id": "P083", "submission_id": "ovuiv6", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nMy (18m) family is going on vacation on Wednesday. It's me, my sister (20f), my half sisters (9 and 8), my half brothers (5 and 3), my dad, and my stepmom. As the oldest, my sister and I are expected to help out with my half siblings whenever their babysitter, our dad, and their mom aren't around. My sister doesn't mind but I hate babysitting them. Whenever I try to tell my stepmom I don't want to babysit her kids, she always tells me I live in her house rent free so I need to help out so we haven't really been on good terms for a while.\n\nMy 8 year old half sister is afraid of everything, including planes and wants my stepmom and my sister to sit with her on the plane. That means my dad will be left with the 9 year old and my brothers. My stepmom won't be able to help because the 8 year old will take all of her attention so she asked me to sit with the 9 year old and help her if she needs anything and to watch one of my half brothers if my dad has to take one of them to the bathroom. \n\nI told her I'm not her babysitter and to take care of her own kids for once instead of relying on me, my sister, and their babysitter. \n\nNow she's threatening to not take me, which I think is unfair considering I didn't do anything wrong, I'm just refusing to be a 3rd parent to her kids. \n\nMy dad is on her side and keeps saying I have to listen to my \"mom\" (she adopted me when I was 2 so he calls her my mom) and my sister thinks I'm being an entitled ass so I wanted to see if I was wrong", "prompt_sha256": "e57d3f983e13c6d1096f28911c03b519c03ee49e68364ac265e7a10079c5d6de", "body_sha256": "f1d371f169a1ecc2c7aae6f40acf4bee7714aeb02c4f8c240d208c4422616e26", "word_limit": 61}, {"stimulus_id": "P084", "submission_id": "16vb87j", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nI am not a dog person mostly because I am allergic and I had a bad experience with one when I was younger so they also scare me a bit. I have 2 small children and often go on walks in my neighborhood with them. If someone is walking their dogs I will either stop and make sure my kids are right next to me until they pass or I will move out of lease range until they pass. I still say hi to them and their owners but a lot of people seem offended when I do this like I’m acting like their dog is dangerous. In my mind, they kind of are? I don’t know them or their dog so in my mind I’m protecting both their dogs and my kids by keeping them separate especially since little kids are jumpy and unpredictable. One person told me that I’m making my kids afraid of dogs by doing this though so I wanted to know if I am the asshole for this. If I am, what should I do instead?", "prompt_sha256": "d140fd540bb00da9fbe69e3261ac2698bbf6d3abe4ebe808fab6ff84470ddba9", "body_sha256": "c849ddbeb1ca053a92e0d914699331a1a59ef3f2f607ff4e1844f107639ccf4f", "word_limit": 61}, {"stimulus_id": "P085", "submission_id": "nop1bs", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nI (18M) went out for lunch with my parents for a celebration. They had asked me what restaurant I’d like to go to, but since it was their celebration, I said that they should pick wherever they want, as long as the restaurant had a couple vegan options for me.\n\nUpon getting to the restaurant and looking at the menu, I find only 1 vegan dish. My parents thought that I could just ask the restaurant to remove meat/dairy from the dishes to make them vegan. This irked me a little, as a) I didn’t want to create extra work for the staff and b) these dishes weren’t simple burgers/pasta/etc where you could just remove ingredients, they were dishes where the meat/dairy were integral parts.\n\nThey kept asking me which dishes I wanted so that we could ask to make it vegan. I repeatedly told them that it was fine, I’d just take the 1 vegan dish, and not to bother with that. However, when the waiter came to take our order, my dad begins asking the waiter if they can make any of the dishes without meat/dairy, loudly saying “we have to take care of our vegan over here,” pointing to me. \n\nAs soon as the waiter left, I snapped at my dad, saying “you don’t have to single me out as vegan.” I was embarrassed, as we had come to a primarily non-vegan/vegetarian restaurant, and my dad was announcing that I was vegan, making me sound entitled, as if I was expecting everyone to accommodate me.\n\nLater on, I ended up apologizing to my dad for snapping at him. He got mad at me because there was no way he would’ve known that I didn’t want him to say that, which I admit I should’ve been more understanding of and should’ve apologized for right off the bat.\n\nHe then began to question me, asking me “What kind of vegan doesn’t want to tell people they’re vegan? Restaurants know how to handle this, why are you so embarrassed?” I explained my reasoning, saying that I thought it would be sufficient to just ask the staff if they could remove meat/dairy, without having to point out who wanted the change and why. I know it’s important to mention things like allergies to the staff, so things don’t get mixed up, but since being vegan is simply a preference of mine, I didn’t think that was necessary.\n\nSo, AITA?\n\nEdit: Thanks everyone for the responses. I just wanted to clarify that my issue was not with the food options themselves, since I see a lot of comments about that. I was totally fine with the food, I was simply embarrassed at my dad’s comment. However, I do understand now that I didn’t need to get as upset about it as I did. Appreciate all your feedback!", "prompt_sha256": "5d386beb5dc5b92529f003d96ad880a812c9418d98ae79fc09bdfd5c195f4347", "body_sha256": "a62697ce3ecc693e9c2ad5714175e08b24a81d2d9ca7f70f33b9b797e9f6483f", "word_limit": 61}, {"stimulus_id": "P086", "submission_id": "yallza", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\n\nMe (f33) and my husband Chris (m36) planned a one week vacation to an out of state ski resort with our 2 kids. His cousin Martin (m38) lost his wife to cancer 6 months ago. She left behind 2 kids nearly same age as my kids (6 &amp;9). My husband is devestated for his best friend's loss, (they're so close that he sees him as a friend) understandably so. He tries to help Martin and kids. But in my opinion? he's been doing a little too much for them lately.\n\nHe suggested we take Martin's kids with us to the resort to get their mind off the grief a bit. I apologized and said it won't wouldn't since we barely have budget to cover for our kids. He insisted then tried offering compromises but I still said it wouldn't work. He was obviously pissed but dropped it eventually.\n\n\n2 days before the trip, I found out that my husband booked two tickets for Martin's kids instead of our own kids. I was the one paying but he insisted on handling thd booking and making reservations. I was stunned...I called him out on it and he apologetically talked about how Martin needs some alone time away from the kids, how the kids need a breather, and how they need this vacation more than our kids do. I flipped out at him asking if he seriously ok with prioritizing others':kids over his own. He said it wasn't about priorities but doing what's needed to help those kids out. I asked how his own kids will react once they find out but he said \"I'm sure they'd understand\". I said no and decided to cancel the vacation altogether. He freaked out on me saying I can't do that and make him look small infront of his cousin and family since they praised him for this \"nice gesture\". I refused to negotiate it but he called me horribly selfish and cruel towards grieving kids and said that he'll make sure our own kids know how I'm behaving towards the other kids by robbing them of the fun they so much need and deserve.\n\n\nWe haven't been talking and he's so pissed and keeps throwing a fit after a fit about it. Claiming I ruined it for everybody when I cancelled.\n\n\nI feel bad for the kids, I do but I don't think what he did was right. Aita for cancelling?", "prompt_sha256": "f21dd4cd0ede759e9f480c948787225363ec362f554b19697819cbb3ec1e9a32", "body_sha256": "59f2219b1fec2327880c837e185c317abfcc70f8a680600cd4dfbad9b9f8dc06", "word_limit": 61}, {"stimulus_id": "P087", "submission_id": "1d7mb89", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nIt sounds really petty and I know it sort of is but I really don’t think this particular situation makes me an asshole. Because of this though a lot of my friends aren’t talking to me. I (23F) have had feelings for Liam (22M) for a while. I wasn’t brave enough to confess my feelings until after he was already involved with another one of our friends Olivia (21F). I didn’t know they were seeing each other when I said anything to him. Truth be told they’ve only been doing this a few months and I think it might be mostly physical, so I’ve been sort of waiting it out until he’s over it.\n\nLast night I had a bunch of friends over, and for the most part everything was cool. Olivia and Liam were crossfaded on the couch next to each other cuddling, or he’d be rubbing her back, or they’d be touching each other’s hair, or he’d be telling her how beautiful she is, or whatever. It was really getting on my nerves. I know it was jealousy but it was still bothering me. I care too much about Liam to let things get out of hand so I tried to ignore it as long as I could. Finally, she like stuck her tongue through his gage (the like ear stretcher things) and he played all grossed out and then playfully licked her face. It like really, really bothered me. I tried to stay chill but then right after that he kissed her and told her he loved her and I was done.\n\nLiam went to the bathroom a few minutes later and Olivia ended up in the kitchen. I followed her and when we were alone I just asked her to leave. She thought I was kidding at first which made me more irritated so the discussion got a bit heated. Finally she just laughed in my face and went to grab her bag and left without saying anything to anyone. No one noticed for a few minutes, it wasn’t until Liam came back that anyone even realized she was gone. I told them that I set a boundary and asked her to leave and left it at that. \n\nHer best friend started getting mad at me because she was crossfaded and it was like 2AM. He started getting his stuff and he told me I was a petty bitch, which started another argument. He ignored me as I was yelling at him, there was a lot of conversation going on, I can’t even tell you what was really said. He said “fuck you” and left.\n\nAt first I didn’t really care, but then Liam didn’t say anything. His best friend asked if he was okay and he was like shifting his jaw, like it was clear he was pissed, and he just shook his head. Liam and his best friend left with Olivia’s best friend. \n\nI was really upset, but I felt like I was laying a boundary in my own home of something that made me uncomfortable. Some understand it’s because of my feelings but others are saying it was petty. I feel like if it’s my house I can set a boundary. Plus she left without saying anything to anyone, it’s not like I forced her out in a fight or something.", "prompt_sha256": "3ab93a31376da1dbf0f0c2a0c12048c7ff01bc2ca4ec3b36754569eb563318a6", "body_sha256": "431d18d87f1df522b4ec3d7db34872cd03a9d8db08f07d8ec0f1596807f428d7", "word_limit": 61}, {"stimulus_id": "P088", "submission_id": "117itt5", "prompt_text": "Read the situation below. Give your judgment of the situation and explain 